@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form.get('username', '').strip()
        password = request.form.get('password', '')
        user = q_one('SELECT * FROM users WHERE username=?', [username])
        if user and verify_password(user['password_hash'], password):
            if len(user['password_hash'] or '') == 64:
                exec_sql('UPDATE users SET password_hash=? WHERE id=?', [hash_password(password), user['id']])
            if not user['active']:
                flash('Akun Anda telah dinonaktifkan oleh admin.', 'error')
                log_action('LOGIN_BLOCKED', 'users', user['id'], 'Login ditolak: akun dinonaktifkan')
                return redirect(url_for('login'))
            if user['role'] != 'admin':
                if str(user['status'] or '').strip().upper() == 'PENDING_APPROVAL':
                    flash('Akun menunggu persetujuan admin.', 'warning')
                    log_action('LOGIN_BLOCKED', 'users', user['id'], 'Login ditolak: status PENDING_APPROVAL')
                    return redirect(url_for('login'))
            session['user_id'] = user['id']
            session['username'] = user['username']
            if user['branch_id']:
                session['branch_id'] = user['branch_id']
            else:
                session.pop('branch_id', None)
            log_action('LOGIN', 'users', user['id'], 'Login berhasil')
            flash(f'✅ Selamat datang, {user["full_name"] or ""}!', 'success')
            return role_home_redirect(user)
        flash('Username atau password salah.', 'error')
    body = r"""
    <div class="coop-login">
      <section class="coop-visual" aria-label="Platform koperasi terpadu">
        <div class="coop-atmosphere" aria-hidden="true"><i></i><i></i><i></i></div>
        <div class="coop-network" aria-hidden="true">
          <span class="network-line line-a"></span><span class="network-line line-b"></span><span class="network-line line-c"></span><span class="network-line line-d"></span>
          <span class="network-node node-a">A</span><span class="network-node node-b">S</span><span class="network-node node-c">K</span><span class="network-node node-d">U</span><span class="network-node node-center">◆</span>
        </div>
        <header class="coop-brand"><div class="coop-mark"><span>◆</span></div><div><b>KOPERASI</b><small>PLATFORM OPERASIONAL TERPADU</small></div></header>
        <div class="coop-story"><span class="coop-kicker">TUMBUH BERSAMA</span><h1>Satu ekosistem untuk anggota, usaha, dan masa depan koperasi.</h1><p>Kelola transaksi, simpanan, kredit, inventori, dan tata kelola melalui alur data yang aman, transparan, serta siap diaudit.</p><div class="coop-principles"><article><i>01</i><div><b>Anggota sebagai pusat</b><small>Setiap layanan terhubung pada kebutuhan anggota.</small></div></article><article><i>02</i><div><b>Data yang dapat dipercaya</b><small>Aktivitas tercatat dan mudah ditelusuri.</small></div></article><article><i>03</i><div><b>Keputusan lebih terukur</b><small>Informasi operasional tersedia dalam satu sistem.</small></div></article></div></div>
        <div class="coop-ticker" aria-hidden="true"><div><span>SIMPANAN</span><b>•</b><span>KREDIT</span><b>•</b><span>USAHA</span><b>•</b><span>ANGGOTA</span><b>•</b><span>TRANSPARANSI</span><b>•</b><span>SIMPANAN</span><b>•</b><span>KREDIT</span><b>•</b><span>USAHA</span></div></div>
      </section>
      <main class="coop-auth">
        <div class="coop-auth-card">
          <div class="coop-auth-mark">◆</div><span class="coop-auth-kicker">AKSES AMAN</span><h2>Selamat datang kembali</h2><p class="coop-auth-sub">Masuk menggunakan akun koperasi yang telah terdaftar.</p>
          {% with messages = get_flashed_messages(with_categories=true) %}{% if messages %}{% for c,m in messages %}<div class="flash flash-{{c}}" role="status">{{m}}</div>{% endfor %}{% endif %}{% endwith %}
          <form method="post" class="coop-form" id="loginForm">
            <div class="coop-field"><label for="username">Username</label><div class="coop-control"><span aria-hidden="true">◎</span><input id="username" name="username" placeholder="Masukkan username" autocomplete="username" required autofocus></div></div>
            <div class="coop-field"><div class="coop-label-row"><label for="password">Password</label><span>Gunakan password akun</span></div><div class="coop-control"><span aria-hidden="true">●</span><input id="password" type="password" name="password" placeholder="Masukkan password" autocomplete="current-password" required><button type="button" class="coop-show" onclick="togglePw()" aria-label="Tampilkan password">Lihat</button></div></div>
            <button class="coop-submit" type="submit"><span>Masuk ke Sistem</span><i aria-hidden="true">→</i></button>
          </form>
          <div class="coop-access-help"><span><a href="{{url_for('forgot_password')}}">Lupa password?</a></span><a href="{{url_for('register')}}">Ajukan pendaftaran</a></div>
          <details class="coop-demo"><summary>Akun demonstrasi</summary><div><button type="button" onclick="fillDemo('admin','admin123')"><b>Administrator</b><small>admin / admin123</small></button><button type="button" onclick="fillDemo('kasir','kasir123')"><b>Kasir</b><small>kasir / kasir123</small></button><button type="button" onclick="fillDemo('bendahara','bendahara123')"><b>Bendahara</b><small>bendahara / bendahara123</small></button></div></details>
          <footer class="coop-auth-footer"><span>Enkripsi password aktif</span><span>Aktivitas tercatat</span></footer>
        </div>
      </main>
    </div>
    <script>
      function togglePw(){var p=document.getElementById('password'),b=document.querySelector('.coop-show');var show=p.type==='password';p.type=show?'text':'password';b.textContent=show?'Sembunyikan':'Lihat';b.setAttribute('aria-label',show?'Sembunyikan password':'Tampilkan password');}
      function fillDemo(u,p){document.getElementById('username').value=u;document.getElementById('password').value=p;document.getElementById('username').dispatchEvent(new Event('input'));}
      document.getElementById('loginForm').addEventListener('submit',function(){var b=this.querySelector('.coop-submit');b.classList.add('loading');b.querySelector('span').textContent='Memverifikasi...';});
    </script>
    """
    return render_page('Login', render_template_string(body))

# =========================
# Auth - Register
# =========================
@app.route('/register', methods=['GET', 'POST'])
def register():
    if 'user_id' in session:
        return redirect(url_for('dashboard'))
    
    try:
        conn = get_conn()
        cur = conn.cursor()
        try:
            cur.execute('ALTER TABLE users ADD COLUMN employee_number TEXT')
            conn.commit()
        except:
            pass
        conn.close()
    except:
        pass
    
    step = request.args.get('step', '1')
    
    if request.method == 'POST':
        if step == '1':
            employee_number = request.form.get('employee_number', '').strip()
            if not employee_number:
                flash('Nomor karyawan wajib diisi.', 'error')
            else:
                exist = q_one('SELECT id FROM users WHERE employee_number = ?', [employee_number])
                if exist:
                    flash('Nomor karyawan ini sudah terdaftar.', 'error')
                else:
                    session['temp_employee_number'] = employee_number
                    flash('Nomor karyawan terverifikasi, silahkan isi data pribadi.', 'success')
                    return redirect(url_for('register', step='2'))
        elif step == '2':
            if 'temp_employee_number' not in session:
                flash('Silahkan masukkan nomor karyawan terlebih dahulu.', 'warning')
                return redirect(url_for('register'))
            full_name = request.form.get('full_name', '').strip()
            phone = request.form.get('phone', '').strip()
            address = request.form.get('address', '').strip()
            password = request.form.get('password', '').strip()
            password_confirm = request.form.get('password_confirm', '').strip()
            if not full_name or not password:
                flash('Nama lengkap dan password wajib diisi.', 'error')
            elif password != password_confirm:
                flash('Password dan konfirmasi password tidak sama.', 'error')
            else:
                exist_user = q_one('SELECT id FROM users WHERE username = ?', [session['temp_employee_number']])
                if exist_user:
                    flash('Nomor karyawan ini sudah terdaftar.', 'error')
                else:
                    try:
                        conn = get_conn()
                        conn.row_factory = sqlite3.Row
                        cur = conn.cursor()
                        try:
                            cur.execute('ALTER TABLE users ADD COLUMN employee_number TEXT UNIQUE')
                        except:
                            pass
                        cur.execute('INSERT INTO users(employee_number, username, full_name, phone, address, password_hash, status, role, active) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)', [
                            session['temp_employee_number'], session['temp_employee_number'], full_name, phone, address, hash_password(password), 'PENDING_APPROVAL', 'user', 0
                        ])
                        uid = cur.lastrowid
                        try:
                            cur.execute('ALTER TABLE members ADD COLUMN member_code TEXT UNIQUE')
                        except:
                            pass
                        try:
                            cur.execute('INSERT INTO members(member_code, name, phone, address, join_date, status) VALUES (?, ?, ?, ?, ?, ?)', [
                                f'EMP-{session["temp_employee_number"]}', full_name, phone, address, today_str(), 'Aktif'
                            ])
                        except sqlite3.IntegrityError:
                            pass
                        conn.commit()
                        conn.close()
                        log_action('REGISTER', 'users', uid, f'Registrasi pegawai {full_name}')
                        session.pop('temp_employee_number', None)
                        admin_users = q_all('SELECT id FROM users WHERE role = "admin"')
                        for a in admin_users:
                            add_notification(a['id'], 'User Baru Mendaftar', f'{full_name} telah mendaftar dan menunggu approval.')
                        flash('Registrasi berhasil! Akun Anda menunggu persetujuan admin.', 'success')
                        return redirect(url_for('login'))
                    except sqlite3.IntegrityError as e:
                        conn.rollback(); conn.close()
                        flash('Terjadi kesalahan saat pendaftaran, silahkan coba lagi.', 'error')
                    except Exception as e:
                        conn.rollback(); conn.close()
                        flash(f'Terjadi error: {str(e)}', 'error')
                    finally:
                        session.pop('temp_employee_number', None)
    
    step_template = '''
    <div class="login-wrap">
      <div class="login-left">
        <div class="login-brand">
          <div class="login-brand-icon">🏠</div>
          <h1>Koperasi Enterprise</h1>
          <p>Bergabunglah sebagai anggota koperasi — nikmati kemudahan belanja, simpanan, dan pinjaman.</p>
          <div class="login-features">
            <div class="login-feat">
              <span class="login-feat-icon">👤</span>
              <div class="login-feat-title">Registrasi Mudah</div>
              <div class="login-feat-desc">Cukup masukkan nomor karyawan dan data pribadi</div>
            </div>
            <div class="login-feat">
              <span class="login-feat-icon">⚡</span>
              <div class="login-feat-title">Aktivasi Cepat</div>
              <div class="login-feat-desc">Akun diaktifkan oleh admin setelah verifikasi</div>
            </div>
            <div class="login-feat">
              <span class="login-feat-icon">💰</span>
              <div class="login-feat-title">E-Wallet</div>
              <div class="login-feat-desc">Topup saldo untuk belanja di koperasi</div>
            </div>
            <div class="login-feat">
              <span class="login-feat-icon">📋</span>
              <div class="login-feat-title">Pinjaman</div>
              <div class="login-feat-desc">Ajukan pinjaman dengan bunga ringan</div>
            </div>
          </div>
        </div>
      </div>
      <div class="login-right">
        <div class="login-card">
          <div class="login-logo">{% if step == '1' %}👤{% else %}✅{% endif %}</div>
          <div class="login-title">Daftar Pegawai</div>
          <div class="login-sub">{% if step == '1' %}Langkah 1/2 — Verifikasi Nomor Karyawan{% else %}Langkah 2/2 — Isi Data Pribadi{% endif %}</div>
          {% if step == '1' %}
          <form method="post">
            <div class="login-field">
              <label>Nomor Karyawan</label>
              <input name="employee_number" placeholder="Masukkan Nomor Karyawan" autofocus>
            </div>
            <button type="submit" class="login-btn">🔍 Verifikasi Nomor Karyawan</button>
          </form>
          {% else %}
          <div class="badge badge-info" style="text-align:center;display:block;margin-bottom:16px;">Nomor Karyawan: {{ session.temp_employee_number }}</div>
          <form method="post">
            <div class="login-field"><label>Nama Lengkap</label><input name="full_name" placeholder="Nama Lengkap"></div>
            <div class="login-field"><label>Nomor HP</label><input name="phone" placeholder="Nomor HP"></div>
            <div class="login-field"><label>Alamat</label><textarea name="address" placeholder="Alamat" style="min-height:60px;"></textarea></div>
            <div class="login-field"><label>Buat Password</label><input type="password" name="password" placeholder="Minimal 4 karakter"></div>
            <div class="login-field"><label>Konfirmasi Password</label><input type="password" name="password_confirm" placeholder="Ulangi password"></div>
            <button type="submit" class="login-btn">📝 Kirim Pendaftaran</button>
          </form>
          {% endif %}
          <div class="login-footer"><a href="{{ url_for('login') }}">Sudah punya akun? Login disini</a></div>
        </div>
      </div>
    </div>
    '''
    body = render_template_string(step_template, step=step)
    return render_page('Daftar Pegawai', body)

