@app.route('/wallet-legacy', methods=['GET', 'POST'])
@login_required
def wallet_legacy():
    user = current_user()
    member = q_one('SELECT * FROM members WHERE member_code = ?', [f'EMP-{user["employee_number"]}'])
    if not member:
        flash('Akun wallet anda belum aktif. Silahkan hubungi admin.', 'warning')
        return redirect(url_for('dashboard'))
    if request.method == 'POST':
        nominal = parse_float(request.form.get('nominal', 0))
        bukti = request.files.get('bukti_transfer')
        if nominal < 10000:
            flash('Nominal topup minimal Rp 10.000', 'error')
        elif not bukti or bukti.filename == '':
            flash('Harap upload bukti transfer', 'error')
        else:
            os.makedirs('uploads', exist_ok=True)
            filename = secure_filename(f'bukti_{user["employee_number"]}_{int(datetime.now().timestamp())}_{bukti.filename}')
            bukti.save(f'uploads/{filename}')
            exec_sql('INSERT INTO topup_requests(member_id, nominal, bukti_foto, status) VALUES (?, ?, ?, ?)', [member['id'], nominal, filename, 'PENDING'])
            log_action('TOPUP_REQUEST', 'topup_requests', member['id'], f'Request topup Rp {nominal}')
            flash('Request topup berhasil dikirim. Menunggu verifikasi admin.', 'success')
            return redirect(url_for('wallet'))
    saldo = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id = ?', [member['id']])['saldo']
    requests = q_all('SELECT * FROM topup_requests WHERE member_id = ? ORDER BY id DESC LIMIT 50', [member['id']])
    history = q_all('SELECT * FROM saldo_history WHERE member_id = ? ORDER BY id DESC LIMIT 50', [member['id']])
    body = render_template_string('''
    <div class="metrics">
        <div class="metric" style="background:linear-gradient(135deg,#eff6ff,#dbeafe);border-color:#bfdbfe;">
            <div class="label">Saldo Wallet</div><div class="value" style="color:#2563eb;">{{ rupiah(saldo) }}</div>
            <div class="sub">{{ member.member_code }}</div>
        </div>
    </div>
    <div class="grid">
        <div class="col-4"><div class="card"><h3>📥 Topup Wallet</h3>
            <form method="post" enctype="multipart/form-data">
                <div class="form-group"><label>Nominal</label><input type="number" name="nominal" min="10000" step="1000" placeholder="Min Rp 10.000"></div>
                <div class="form-group" style="padding:12px;background:#f9fafb;border-radius:8px;text-align:center;border:1px dashed var(--border);">
                    <div style="font-size:13px;color:var(--text-muted);">Transfer ke:</div>
                    <div style="font-size:18px;font-weight:700;color:#2563eb;">BCA 1234567890</div>
                    <div class="muted small">a.n. Koperasi Enterprise</div>
                </div>
                <div class="form-group"><label>Bukti Transfer</label><input type="file" name="bukti_transfer" accept="image/*" required></div>
                <button type="submit">📤 Kirim Request</button>
            </form>
        </div></div>
        <div class="col-8"><div class="card"><h3>📋 Riwayat Topup</h3>
            <div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Nominal</th><th>Status</th></tr></thead>
            <tbody>{% for r in requests %}<tr><td>{{ r.created_at }}</td><td>{{ rupiah(r.nominal) }}</td>
            <td><span class="badge {{ 'badge-warn' if r.status == 'PENDING' else 'badge-success' if r.status == 'APPROVED' else 'badge-danger' }}">{{ r.status }}</span></td></tr>{% else %}<tr><td colspan="3" class="muted text-center">Belum ada request.</td></tr>{% endfor %}</tbody></table></div>
        </section>
    </div>
    ''', member=member, saldo=saldo, requests=requests, history=history, rupiah=rupiah)
    return render_page('Wallet Saya', body)


# =========================
# Member Experience Suite - 5 member features
# Savings Goals, Financial Calendar, Member Benefits, Service Requests, Personal Insights
# =========================
def ensure_member_experience_tables():
    conn=get_conn(); c=conn.cursor()
    for sql in [
      "CREATE TABLE IF NOT EXISTS member_savings_goals(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER,title TEXT,target_amount REAL,current_amount REAL DEFAULT 0,target_date TEXT,category TEXT,status TEXT DEFAULT 'ACTIVE',created_at TEXT DEFAULT CURRENT_TIMESTAMP,completed_at TEXT)",
      "CREATE TABLE IF NOT EXISTS member_goal_contributions(id INTEGER PRIMARY KEY AUTOINCREMENT,goal_id INTEGER,amount REAL,note TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS member_benefits(id INTEGER PRIMARY KEY AUTOINCREMENT,title TEXT,description TEXT,benefit_type TEXT,value_text TEXT,valid_from TEXT,valid_until TEXT,terms TEXT,status TEXT DEFAULT 'ACTIVE',created_at TEXT DEFAULT CURRENT_TIMESTAMP)",
      "CREATE TABLE IF NOT EXISTS member_benefit_claims(id INTEGER PRIMARY KEY AUTOINCREMENT,benefit_id INTEGER,member_id INTEGER,claim_code TEXT UNIQUE,status TEXT DEFAULT 'CLAIMED',claimed_at TEXT DEFAULT CURRENT_TIMESTAMP,used_at TEXT,UNIQUE(benefit_id,member_id))",
      "CREATE TABLE IF NOT EXISTS member_service_requests(id INTEGER PRIMARY KEY AUTOINCREMENT,request_no TEXT UNIQUE,member_id INTEGER,category TEXT,subject TEXT,description TEXT,priority TEXT DEFAULT 'NORMAL',status TEXT DEFAULT 'OPEN',response TEXT,created_at TEXT DEFAULT CURRENT_TIMESTAMP,updated_at TEXT)",
      "CREATE TABLE IF NOT EXISTS member_preferences(id INTEGER PRIMARY KEY AUTOINCREMENT,member_id INTEGER UNIQUE,monthly_budget REAL DEFAULT 0,savings_target_percent REAL DEFAULT 10,reminder_days INTEGER DEFAULT 3,show_balance INTEGER DEFAULT 1,updated_at TEXT)"
    ]: c.execute(sql)
    # seed mature but neutral benefits once
    if c.execute('SELECT COUNT(*) FROM member_benefits').fetchone()[0]==0:
        c.executemany('INSERT INTO member_benefits(title,description,benefit_type,value_text,valid_from,valid_until,terms,status) VALUES(?,?,?,?,?,?,?,"ACTIVE")',[
          ('Prioritas Layanan','Jalur layanan lebih cepat untuk anggota aktif.','SERVICE','Prioritas antrean',today_str(),None,'Berlaku untuk anggota berstatus aktif.'),
          ('Pemeriksaan Finansial','Ringkasan kesehatan finansial anggota.','EDUCATION','Gratis',today_str(),None,'Dapat digunakan satu kali setiap bulan.'),
          ('Program Belanja Anggota','Manfaat belanja pada program koperasi terpilih.','SHOPPING','Program berkala',today_str(),None,'Mengikuti ketentuan toko dan periode program.')])
    conn.commit();conn.close()

def current_member_required():
    u=current_user(); return q_one('SELECT * FROM members WHERE member_code=?',[f'EMP-{u["employee_number"]}'])

@app.route('/member/hub',methods=['GET','POST'])
@login_required
@role_required('user')
def member_hub():
    ensure_member_experience_tables(); member=current_member_required(); user=current_user()
    if not member: flash('Profil anggota belum tersedia.','error'); return redirect(url_for('member_dashboard'))
    mid=member['id']; tab=request.args.get('tab','goals'); tabs={'goals':'Target','calendar':'Kalender','benefits':'Manfaat','requests':'Layanan','insights':'Insight'}
    if tab not in tabs: tab='goals'
    if request.method=='POST':
        action=request.form.get('action','')
        try:
            if action=='create_goal':
                title=request.form.get('title','').strip(); target=parse_float(request.form.get('target_amount',0))
                if len(title)<3 or target<=0: raise ValueError('Nama target dan nominal harus valid.')
                exec_sql('INSERT INTO member_savings_goals(member_id,title,target_amount,target_date,category,status) VALUES(?,?,?,?,?,"ACTIVE")',[mid,title,target,request.form.get('target_date') or None,request.form.get('category','Umum')]); log_action('MEMBER_GOAL_CREATE','member_savings_goals',mid,title); flash('Target finansial berhasil dibuat.','success')
            elif action=='contribute_goal':
                gid=int(request.form.get('goal_id') or 0); amount=parse_float(request.form.get('amount',0)); goal=q_one('SELECT * FROM member_savings_goals WHERE id=? AND member_id=?',[gid,mid])
                if not goal or amount<=0: raise ValueError('Target atau nominal tidak valid.')
                new=float(goal['current_amount'] or 0)+amount; status='COMPLETED' if new>=float(goal['target_amount'] or 0) else 'ACTIVE'; exec_sql('UPDATE member_savings_goals SET current_amount=?,status=?,completed_at=? WHERE id=?',[new,status,now_str() if status=='COMPLETED' else None,gid]); exec_sql('INSERT INTO member_goal_contributions(goal_id,amount,note) VALUES(?,?,?)',[gid,amount,request.form.get('note')]); log_action('MEMBER_GOAL_CONTRIBUTE','member_savings_goals',gid,str(amount)); flash('Perkembangan target berhasil diperbarui.','success')
            elif action=='claim_benefit':
                bid=int(request.form.get('benefit_id') or 0); benefit=q_one('SELECT * FROM member_benefits WHERE id=? AND status="ACTIVE"',[bid])
                if not benefit: raise ValueError('Manfaat tidak tersedia.')
                exec_sql('INSERT INTO member_benefit_claims(benefit_id,member_id,claim_code) VALUES(?,?,?)',[bid,mid,gen_code('CLM')]); log_action('MEMBER_BENEFIT_CLAIM','member_benefit_claims',bid,member['member_code']); flash('Manfaat berhasil diklaim.','success')
            elif action=='service_request':
                subject=request.form.get('subject','').strip(); desc=request.form.get('description','').strip()
                if len(subject)<3 or len(desc)<10: raise ValueError('Subjek minimal 3 dan penjelasan minimal 10 karakter.')
                no=gen_code('REQ'); exec_sql('INSERT INTO member_service_requests(request_no,member_id,category,subject,description,priority,status) VALUES(?,?,?,?,?,? ,"OPEN")',[no,mid,request.form.get('category'),subject,desc,request.form.get('priority','NORMAL')]); log_action('MEMBER_SERVICE_REQUEST','member_service_requests',mid,no); flash(f'Permintaan {no} berhasil dikirim.','success')
            elif action=='save_preference':
                budget=max(0,parse_float(request.form.get('monthly_budget',0))); pct=max(0,min(100,parse_float(request.form.get('savings_target_percent',10)))); days=max(0,min(30,int(request.form.get('reminder_days') or 3))); exec_sql('INSERT INTO member_preferences(member_id,monthly_budget,savings_target_percent,reminder_days,show_balance,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(member_id) DO UPDATE SET monthly_budget=excluded.monthly_budget,savings_target_percent=excluded.savings_target_percent,reminder_days=excluded.reminder_days,show_balance=excluded.show_balance,updated_at=excluded.updated_at',[mid,budget,pct,days,1 if request.form.get('show_balance') else 0,now_str()]); flash('Preferensi finansial berhasil disimpan.','success')
        except (ValueError,sqlite3.IntegrityError) as e: flash(str(e) if isinstance(e,ValueError) else 'Data tersebut sudah pernah diproses.','error')
        return redirect(url_for('member_hub',tab=tab))
    goals=q_all('SELECT * FROM member_savings_goals WHERE member_id=? ORDER BY CASE status WHEN "ACTIVE" THEN 0 ELSE 1 END,id DESC',[mid]); benefits=q_all('SELECT b.*,c.claim_code,c.status claim_status FROM member_benefits b LEFT JOIN member_benefit_claims c ON c.benefit_id=b.id AND c.member_id=? WHERE b.status="ACTIVE" ORDER BY b.id DESC',[mid]); requests=q_all('SELECT * FROM member_service_requests WHERE member_id=? ORDER BY id DESC',[mid]); pref=q_one('SELECT * FROM member_preferences WHERE member_id=?',[mid]) or {'monthly_budget':0,'savings_target_percent':10,'reminder_days':3,'show_balance':1}
    flows=[]
    for r in q_all('SELECT loan_no,monthly_installment FROM loans WHERE member_id=? AND status="Berjalan"',[mid]): flows.append({'date':'Bulanan','title':'Angsuran '+r['loan_no'],'amount':r['monthly_installment'],'kind':'loan'})
    for r in goals:
        if r['target_date'] and r['status']=='ACTIVE': flows.append({'date':r['target_date'],'title':'Target '+r['title'],'amount':max(0,float(r['target_amount'])-float(r['current_amount'])),'kind':'goal'})
    spend=q_one('SELECT COALESCE(SUM(total),0) x FROM sales WHERE member_id=? AND status="Posted" AND substr(trx_date,1,7)=?',[mid,datetime.now().strftime('%Y-%m')])['x'] or 0; savings=q_one("SELECT COALESCE(SUM(CASE WHEN direction='Masuk' THEN amount ELSE -amount END),0) x FROM savings_transactions WHERE member_id=?",[mid])['x'] or 0; loan_remaining=q_one('SELECT COALESCE(SUM(total_receivable),0) x FROM loans WHERE member_id=? AND status="Berjalan"',[mid])['x'] or 0; budget=float(pref['monthly_budget'] or 0); budget_pct=min(100,spend/budget*100) if budget else 0
    body=render_template_string(r'''
    <div class="mh-app"><header class="mh-head"><a href="{{url_for('member_dashboard')}}">←</a><div><span>RUANG ANGGOTA</span><h2>{{tabs[tab]}}</h2></div></header><nav class="mh-tabs">{% for k,v in tabs.items() %}<a class="{{'active' if tab==k}}" href="{{url_for('member_hub',tab=k)}}">{{v}}</a>{% endfor %}</nav>
    {% if tab=='goals' %}<section class="mh-compose"><h3>Buat target baru</h3><form method="post"><input type="hidden" name="action" value="create_goal"><input name="title" placeholder="Contoh: Dana pendidikan" required><div class="mh-two"><input type="number" name="target_amount" min="1" placeholder="Target nominal" required><input type="date" name="target_date"></div><select name="category"><option>Umum</option><option>Pendidikan</option><option>Darurat</option><option>Rumah</option><option>Kendaraan</option></select><button>Buat target</button></form></section><div class="mh-stack">{% for g in goals %}<article class="mh-goal"><div><span>{{g.category}} · {{g.status}}</span><h3>{{g.title}}</h3><b>{{rupiah(g.current_amount)}} <small>dari {{rupiah(g.target_amount)}}</small></b></div><div class="mh-ring" style="--p:{{[100,((g.current_amount/(g.target_amount or 1))*100)]|min|round}}"><i>{{[100,((g.current_amount/(g.target_amount or 1))*100)]|min|round}}%</i></div>{% if g.status=='ACTIVE' %}<form method="post"><input type="hidden" name="action" value="contribute_goal"><input type="hidden" name="goal_id" value="{{g.id}}"><input type="number" name="amount" min="1" placeholder="Tambah progres" required><button>Tambah</button></form>{% endif %}</article>{% else %}<div class="mh-empty">Belum ada target finansial.</div>{% endfor %}</div>
    {% elif tab=='calendar' %}<section class="mh-calendar-head"><span>{{now().strftime('%B %Y')}}</span><h3>Agenda finansial</h3><p>Jatuh tempo, target, dan kewajiban dalam satu urutan.</p></section><div class="mh-timeline">{% for f in flows %}<article><i class="{{f.kind}}"></i><div><span>{{f.date}}</span><b>{{f.title}}</b></div><strong>{{rupiah(f.amount)}}</strong></article>{% else %}<div class="mh-empty">Tidak ada agenda finansial aktif.</div>{% endfor %}</div>
    {% elif tab=='benefits' %}<div class="mh-stack">{% for b in benefits %}<article class="mh-benefit"><span>{{b.benefit_type}}</span><h3>{{b.title}}</h3><p>{{b.description}}</p><strong>{{b.value_text}}</strong>{% if b.claim_code %}<div class="mh-claimed">Kode: {{b.claim_code}}</div>{% else %}<form method="post"><input type="hidden" name="action" value="claim_benefit"><input type="hidden" name="benefit_id" value="{{b.id}}"><button>Klaim manfaat</button></form>{% endif %}</article>{% else %}<div class="mh-empty">Belum ada manfaat tersedia.</div>{% endfor %}</div>
    {% elif tab=='requests' %}<section class="mh-compose"><h3>Buat permintaan layanan</h3><form method="post"><input type="hidden" name="action" value="service_request"><select name="category"><option>Data Keanggotaan</option><option>Simpanan</option><option>Kredit</option><option>Transaksi</option><option>Lainnya</option></select><input name="subject" placeholder="Subjek" required><textarea name="description" placeholder="Jelaskan kebutuhan secara lengkap" minlength="10" required></textarea><select name="priority"><option>NORMAL</option><option>HIGH</option></select><button>Kirim permintaan</button></form></section><div class="mh-stack">{% for r in requests %}<article class="mh-request"><div><span>{{r.request_no}} · {{r.category}}</span><h3>{{r.subject}}</h3><p>{{r.description}}</p></div><b class="{{r.status|lower}}">{{r.status}}</b>{% if r.response %}<blockquote>{{r.response}}</blockquote>{% endif %}</article>{% else %}<div class="mh-empty">Belum ada permintaan layanan.</div>{% endfor %}</div>
    {% else %}<section class="mh-insight-hero"><span>RINGKASAN BULAN INI</span><h3>{{rupiah(spend)}}</h3><p>Total belanja tercatat</p><div class="mh-budget"><i style="width:{{budget_pct}}%"></i></div><small>{% if budget %}{{budget_pct|round}}% dari anggaran {{rupiah(budget)}}{% else %}Atur anggaran untuk memantau pengeluaran{% endif %}</small></section><div class="mh-insights"><article><span>Simpanan bersih</span><b>{{rupiah(savings)}}</b><p>{% if savings>0 %}Fondasi simpanan sudah terbentuk.{% else %}Mulai target simpanan secara bertahap.{% endif %}</p></article><article><span>Kewajiban kredit</span><b>{{rupiah(loan_remaining)}}</b><p>{% if loan_remaining>0 %}Pantau jadwal dan bayar sebelum jatuh tempo.{% else %}Tidak ada kredit aktif.{% endif %}</p></article></div><section class="mh-compose"><h3>Preferensi insight</h3><form method="post"><input type="hidden" name="action" value="save_preference"><input type="number" name="monthly_budget" min="0" value="{{pref.monthly_budget}}" placeholder="Anggaran bulanan"><input type="number" name="savings_target_percent" min="0" max="100" value="{{pref.savings_target_percent}}" placeholder="Target simpanan %"><input type="number" name="reminder_days" min="0" max="30" value="{{pref.reminder_days}}" placeholder="Pengingat H-berapa"><label class="mh-check"><input type="checkbox" name="show_balance" {% if pref.show_balance %}checked{% endif %}> Tampilkan saldo di beranda</label><button>Simpan preferensi</button></form></section>{% endif %}
    </div>
    ''',tab=tab,tabs=tabs,goals=goals,benefits=benefits,requests=requests,flows=flows,pref=pref,spend=spend,savings=savings,loan_remaining=loan_remaining,budget=budget,budget_pct=budget_pct,rupiah=rupiah,now=lambda:datetime.now())
    return render_page(tabs[tab],body)

