@app.route('/member/dashboard', methods=['GET'])
@login_required
def member_dashboard():
    # Tabel fitur pembayaran tidak selalu sudah terbentuk pada database Render lama/baru.
    # Pastikan tabel tersedia sebelum query aktivitas anggota dijalankan.
    ensure_branch_qr_payment_schema()
    ensure_payment_code_schema()

    user = current_user()
    if not user:
        session.clear()
        return redirect(url_for('login'))

    employee_number = str(user['employee_number'] or '').strip()
    if not employee_number:
        flash('Nomor karyawan akun belum tersedia. Hubungi admin koperasi.', 'warning')
        return redirect(url_for('settings'))

    member = q_one('SELECT * FROM members WHERE member_code=?', [f'EMP-{employee_number}'])
    if not member:
        flash('Profil anggota belum terhubung. Hubungi pengelola koperasi.', 'warning')
        return redirect(url_for('settings'))
    mid=member['id']; saldo_wallet=q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END),0) saldo FROM saldo_history WHERE member_id=?',[mid])['saldo'] or 0
    total_simpanan=q_one("SELECT COALESCE(SUM(CASE WHEN direction='Masuk' THEN amount ELSE -amount END),0) x FROM savings_transactions WHERE member_id=?",[mid])['x'] or 0
    total_belanja=q_one('SELECT COALESCE(SUM(total),0) x FROM sales WHERE member_id=? AND status="Posted"',[mid])['x'] or 0
    active_loan=q_one('SELECT * FROM loans WHERE member_id=? AND status="Berjalan" ORDER BY id DESC LIMIT 1',[mid])
    next_due=None
    if active_loan: next_due=q_one('SELECT * FROM loan_schedules WHERE loan_id=? AND COALESCE(status,"BELUM_BAYAR") NOT IN ("LUNAS","PAID") ORDER BY CASE WHEN due_date IS NULL OR due_date="" THEN 1 ELSE 0 END, due_date ASC, installment_number ASC, id ASC LIMIT 1',[active_loan['id']])
    paid=q_one('SELECT COALESCE(SUM(lp.amount),0) x FROM loan_payments lp JOIN loans l ON l.id=lp.loan_id WHERE l.member_id=? AND lp.status="VERIFIED"',[mid])['x'] or 0
    shu=calculate_shu(mid,datetime.now().year)
    recent=q_all('''SELECT reference_no,trx_time,total,source FROM (
      SELECT invoice_no reference_no,trx_date trx_time,total,'KASIR' source,id sort_id FROM sales WHERE member_id=? AND status='Posted'
      UNION ALL
      SELECT payment_code reference_no,paid_at trx_time,amount total,'QR' source,id sort_id FROM branch_qr_payment_intents WHERE member_id=? AND status='PAID'
      UNION ALL
      SELECT payment_no reference_no,created_at trx_time,amount total,'KODE 3D' source,id sort_id FROM branch_code_payments WHERE member_id=? AND status='PAID'
    ) ORDER BY trx_time DESC,sort_id DESC LIMIT 4''',[mid,mid,mid])
    unread=q_one('SELECT COUNT(*) n FROM notifications WHERE user_id=? AND is_read=0',[user['id']])['n'] or 0
    goals=0; open_requests=0
    try:
        ensure_member_experience_tables()
        goals=q_one('SELECT COUNT(*) n FROM member_savings_goals WHERE member_id=? AND status="ACTIVE"',[mid])['n'] or 0
        open_requests=q_one('SELECT COUNT(*) n FROM member_service_requests WHERE member_id=? AND status IN ("OPEN","IN_PROGRESS")',[mid])['n'] or 0
    except Exception: pass
    remaining=max(0,float(active_loan['total_receivable'] or 0)-float(paid)) if active_loan else 0
    body=render_template_string(r'''
    <div class="premium-home">
      <section class="ph-hero">
        <div class="ph-orb ph-orb-a"></div><div class="ph-orb ph-orb-b"></div><div class="ph-grid"></div>
        <header class="ph-hero-head">
          <div class="ph-identity">
            <span class="ph-member-mark" aria-hidden="true">◆</span>
            <div><small>SELAMAT DATANG</small><h1>{{member.name.split()[0]}}</h1><p>{{member.member_code}} · Anggota sejak {{member.join_date or '-'}}</p></div>
          </div>
          <a href="{{url_for('notifications')}}" class="ph-notification" aria-label="Notifikasi"><span>◌</span>{% if unread %}<b>{{unread if unread < 100 else '99+'}}</b>{% endif %}</a>
        </header>
        <div class="ph-wealth">
          <div class="ph-wealth-copy"><span>TOTAL ASET KOPERASI</span><strong>{{rupiah(saldo_wallet+total_simpanan+shu)}}</strong><small>Dompet, simpanan, dan estimasi SHU tahun {{now().year}}</small></div>
          <div class="ph-asset-mark" aria-hidden="true"><i></i><b>ASET</b><small>TERHUBUNG</small></div>
        </div>
        <div class="ph-actions">
          <a href="{{url_for('wallet')}}"><i>＋</i><span><b>Isi Saldo</b><small>Top up dompet</small></span></a>
          <a href="{{url_for('apply_loan')}}"><i>↗</i><span><b>Ajukan Kredit</b><small>Proses digital</small></span></a>
          <a href="{{url_for('member_digital_card')}}"><i>◇</i><span><b>Kartu Digital</b><small>Identitas anggota</small></span></a>
        </div>
      </section>

      <section class="ph-assets">
        <article class="ph-asset-card ph-wallet"><div class="ph-card-icon">◎</div><div><span>Dompet aktif</span><strong>{{rupiah(saldo_wallet)}}</strong><small>Saldo siap digunakan</small></div><a href="{{url_for('wallet')}}">›</a></article>
        <article class="ph-asset-card ph-saving"><div class="ph-card-icon">◉</div><div><span>Total simpanan</span><strong>{{rupiah(total_simpanan)}}</strong><small>Akumulasi bersih</small></div><a href="{{url_for('member_expense_history')}}">›</a></article>
        <article class="ph-asset-card ph-shu"><div class="ph-card-icon">✦</div><div><span>Estimasi SHU {{now().year}}</span><strong>{{rupiah(shu)}}</strong><small>Nilai sementara</small></div><a href="{{url_for('shu_member')}}">›</a></article>
      </section>

      {% if active_loan %}<section class="ph-credit">
        <header><div><span class="ph-eyebrow">KREDIT AKTIF</span><h2>Tagihan berikutnya</h2></div><a href="{{url_for('loans')}}">Lihat detail <b>›</b></a></header>
        <div class="ph-credit-main"><div><small>Sisa tagihan</small><strong>{{rupiah(remaining)}}</strong><p>{{active_loan.loan_no}}</p></div><div class="ph-due"><span>JATUH TEMPO</span><b>{{next_due.due_date if next_due else '-'}}</b><small>{{rupiah(active_loan.monthly_installment)}} / angsuran</small></div></div>
        <div class="ph-progress-head"><span>Progres pembayaran</span><b>{{[100,((paid/(active_loan.total_receivable or 1))*100)]|min|round|int}}%</b></div><div class="ph-progress"><i style="width:{{[100,((paid/(active_loan.total_receivable or 1))*100)]|min|round}}%"></i></div>
        <a class="ph-pay" href="{{url_for('pay_loan_installment',loan_id=active_loan.id)}}"><span>Bayar angsuran</span><b>→</b></a>
      </section>{% else %}<section class="ph-credit ph-credit-empty"><div><span class="ph-eyebrow">KREDIT</span><h2>Belum ada kredit aktif</h2><p>Ajukan kebutuhan produktif melalui proses digital koperasi.</p></div><a href="{{url_for('apply_loan')}}">Ajukan sekarang →</a></section>{% endif %}

      <section class="ph-services">
        <header class="ph-section-head"><div><span class="ph-eyebrow">LAYANAN EKSKLUSIF</span><h2>Semua kebutuhan dalam satu sentuhan</h2></div><a href="{{url_for('member_hub')}}">Lihat semua</a></header>
        <div class="ph-service-grid">
          <a href="{{url_for('member_hub',tab='goals')}}"><i>◎</i><b>Target</b><small>{{goals}} aktif</small><em>›</em></a>
          <a href="{{url_for('member_hub',tab='calendar')}}"><i>▦</i><b>Kalender</b><small>Agenda finansial</small><em>›</em></a>
          <a href="{{url_for('member_hub',tab='benefits')}}"><i>✦</i><b>Manfaat</b><small>Benefit anggota</small><em>›</em></a>
          <a href="{{url_for('member_hub',tab='requests')}}"><i>◫</i><b>Layanan</b><small>{{open_requests}} diproses</small><em>›</em></a>
          <a href="{{url_for('member_hub',tab='insights')}}"><i>⌁</i><b>Insight</b><small>Analisis pribadi</small><em>›</em></a>
          <a href="{{url_for('member_purchases')}}"><i>≡</i><b>Aktivitas</b><small>Riwayat transaksi</small><em>›</em></a>
        </div>
      </section>

      <section class="ph-activity">
        <header class="ph-section-head"><div><span class="ph-eyebrow">AKTIVITAS TERKINI</span><h2>Pergerakan dana terbaru</h2></div><a href="{{url_for('member_purchases')}}">Semua</a></header>
        <div class="ph-activity-list">{% for r in recent %}<a href="{{url_for('member_purchases')}}"><i>↙</i><span><b>Pembayaran kantin · {{r.source}}</b><small>{{r.reference_no}} · {{r.trx_time}}</small></span><strong>-{{rupiah(r.total)}}</strong></a>{% else %}<div class="ph-empty"><i>◇</i><b>Belum ada aktivitas</b><span>Transaksi terbaru akan tampil di sini.</span></div>{% endfor %}</div>
      </section>
      <footer class="ph-trust"><span>◈ Data terlindungi</span><span>● Sistem aktif</span><span>✓ Transaksi tercatat</span></footer>
    </div>
    ''',member=member,user=user,saldo_wallet=saldo_wallet,total_simpanan=total_simpanan,shu=shu,active_loan=active_loan,next_due=next_due,paid=paid,remaining=remaining,recent=recent,unread=unread,goals=goals,open_requests=open_requests,rupiah=rupiah,now=lambda:datetime.now)
    return render_page('Beranda',body)

# =========================
# Member Purchase History
# =========================
@app.route('/member/purchases', methods=['GET'])
@login_required
def member_purchases():
    ensure_branch_qr_payment_schema(); ensure_payment_code_schema()
    user=current_user(); member=q_one('SELECT * FROM members WHERE member_code=?',[f'EMP-{user["employee_number"]}'])
    if not member:
        flash('Akun member tidak ditemukan.','warning'); return redirect(url_for('dashboard'))
    start_date,end_date=date_range_from_request(); payment_source=(request.args.get('source') or '').upper(); params=[member['id'],member['id'],member['id']]
    sql='''SELECT * FROM (
      SELECT s.id record_id,'SALE' source,s.invoice_no reference_no,s.trx_date paid_at,s.total amount,s.payment_method method,
             s.branch_id,COALESCE(b.name,'PUSAT') branch_name,s.cashier_id operator_user_id,s.cashier_session_id,
             COALESCE(u.full_name,u.username,'-') operator_name,'Belanja kasir' description
      FROM sales s LEFT JOIN users u ON u.id=s.cashier_id LEFT JOIN koperasi_branches b ON b.id=s.branch_id
      WHERE s.member_id=? AND s.status='Posted'
      UNION ALL
      SELECT i.id record_id,'QR' source,i.payment_code reference_no,i.paid_at,i.amount,'WALLET' method,
             i.branch_id,COALESCE(b.name,'PUSAT') branch_name,i.operator_user_id,i.cashier_session_id,
             COALESCE(u.full_name,u.username,'Belum terhubung') operator_name,
             CASE WHEN i.qr_mode='DYNAMIC' THEN 'QR nominal' ELSE 'QR statis cabang' END description
      FROM branch_qr_payment_intents i LEFT JOIN users u ON u.id=i.operator_user_id LEFT JOIN koperasi_branches b ON b.id=i.branch_id
      WHERE i.member_id=? AND i.status='PAID'
      UNION ALL
      SELECT p.id record_id,'KODE_3D' source,p.payment_no reference_no,p.created_at paid_at,p.amount,'WALLET' method,
             p.branch_id,COALESCE(b.name,'PUSAT') branch_name,p.operator_user_id,p.cashier_session_id,
             COALESCE(u.full_name,u.username,'Belum terhubung') operator_name,'Kode cabang '||p.code description
      FROM branch_code_payments p LEFT JOIN users u ON u.id=p.operator_user_id LEFT JOIN koperasi_branches b ON b.id=p.branch_id
      WHERE p.member_id=? AND p.status='PAID'
    ) x WHERE 1=1'''
    if start_date: sql+=' AND substr(x.paid_at,1,10)>=?'; params.append(start_date)
    if end_date: sql+=' AND substr(x.paid_at,1,10)<=?'; params.append(end_date)
    if payment_source in ('SALE','QR','KODE_3D'): sql+=' AND x.source=?'; params.append(payment_source)
    base_sql=sql
    base_params=list(params)
    page=max(1,request.args.get('page',1,type=int) or 1)
    allowed_per_page=(10,20,30,50)
    per_page=request.args.get('per_page',10,type=int) or 10
    if per_page not in allowed_per_page: per_page=10
    summary=q_one(f'''SELECT COUNT(*) total_count,COALESCE(SUM(amount),0) total_amount,
                      SUM(CASE WHEN source='QR' THEN 1 ELSE 0 END) qr_count,
                      SUM(CASE WHEN source='KODE_3D' THEN 1 ELSE 0 END) code_count,
                      SUM(CASE WHEN source='SALE' THEN 1 ELSE 0 END) sale_count
                      FROM ({base_sql})''',base_params)
    total_count=int(summary['total_count'] or 0); total_pages=max(1,(total_count+per_page-1)//per_page)
    if page>total_pages: page=total_pages
    offset=(page-1)*per_page
    rows=q_all(base_sql+' ORDER BY x.paid_at DESC,x.record_id DESC LIMIT ? OFFSET ?',base_params+[per_page,offset])
    p={'page':page,'per_page':per_page,'total':total_count,'total_pages':total_pages}
    pagination_html=render_pagination(p,'member_purchases',{'start':start_date,'end':end_date,'source':payment_source,'per_page':per_page})
    total_all=float(summary['total_amount'] or 0); qr_count=int(summary['qr_count'] or 0); code_count=int(summary['code_count'] or 0); sale_count=int(summary['sale_count'] or 0)
    body=render_template_string(r'''<div class="member-canteen-history"><header class="mch-hero"><div><span>CANTEEN PAYMENT RECORD</span><h2>Riwayat Pembayaran Kantin</h2><p>Semua transaksi kasir, scan QR, dan kode 3 digit tersimpan bersama operator serta struk digital.</p></div><div><strong>{{p.total}}</strong><small>total transaksi</small></div></header><section class="mch-kpis"><article><span>Total periode</span><b>{{rupiah(total_all)}}</b></article><article><span>QR Payment</span><b>{{qr_count}}</b></article><article><span>Kode 3 digit</span><b>{{code_count}}</b></article><article><span>Kasir</span><b>{{sale_count}}</b></article></section><section class="mch-panel"><form method="get" class="mch-filter"><input type="date" name="start" value="{{start}}"><input type="date" name="end" value="{{end}}"><select name="source"><option value="">Semua metode</option><option value="SALE" {{'selected' if payment_source=='SALE'}}>Kasir</option><option value="QR" {{'selected' if payment_source=='QR'}}>QR</option><option value="KODE_3D" {{'selected' if payment_source=='KODE_3D'}}>Kode 3 digit</option></select><select name="per_page"><option value="10" {{'selected' if p.per_page==10}}>10 / halaman</option><option value="20" {{'selected' if p.per_page==20}}>20 / halaman</option><option value="30" {{'selected' if p.per_page==30}}>30 / halaman</option><option value="50" {{'selected' if p.per_page==50}}>50 / halaman</option></select><button>Terapkan</button></form><div class="mch-list">{% for r in rows %}<article><div class="mch-source {{r.source|lower}}">{{'▦' if r.source=='QR' else '123' if r.source=='KODE_3D' else '▣'}}</div><div class="mch-main"><span>{{r.source}} · {{r.branch_name}}</span><b>{{r.description}}</b><small>{{r.reference_no}} · {{r.paid_at}}</small><p>Operator: <strong>{{r.operator_name}}</strong> · Sesi #{{r.cashier_session_id or '-'}}</p></div><strong class="mch-amount">-{{rupiah(r.amount)}}</strong><a href="{{url_for('member_payment_receipt',source=r.source,record_id=r.record_id)}}">Lihat Struk</a></article>{% else %}<div class="mch-empty">Belum ada pembayaran kantin pada periode ini.</div>{% endfor %}</div><footer class="mch-pagination"><div><b>Halaman {{p.page}} dari {{p.total_pages}}</b><small>Menampilkan {{rows|length}} dari {{p.total}} transaksi</small></div>{{pagination_html|safe}}</footer></section></div>''',rows=rows,total_all=total_all,qr_count=qr_count,code_count=code_count,sale_count=sale_count,start=start_date,end=end_date,payment_source=payment_source,p=p,pagination_html=pagination_html,rupiah=rupiah)
    return render_page('Riwayat Pembayaran Kantin',body)

@app.route('/member/payment-receipt/<source>/<int:record_id>')
@login_required
def member_payment_receipt(source,record_id):
    ensure_branch_qr_payment_schema(); ensure_payment_code_schema()
    user=current_user(); member=q_one('SELECT * FROM members WHERE member_code=?',[f'EMP-{user["employee_number"]}'])
    if not member: return ('Member tidak ditemukan',404)
    source=source.upper(); row=None
    if source=='SALE':
        sale=q_one('''SELECT s.id,s.invoice_no reference_no,s.trx_date paid_at,s.total amount,s.payment_method method,s.cashier_session_id,
                      COALESCE(b.name,'PUSAT') branch_name,COALESCE(u.full_name,u.username,'-') operator_name
                      FROM sales s LEFT JOIN users u ON u.id=s.cashier_id LEFT JOIN koperasi_branches b ON b.id=s.branch_id
                      WHERE s.id=? AND s.member_id=? AND s.status='Posted' ''',[record_id,member['id']])
        if sale: return redirect(url_for('receipt_pdf',sale_id=record_id))
    elif source=='QR':
        row=q_one('''SELECT i.payment_code reference_no,i.paid_at,i.amount,'WALLET' method,i.cashier_session_id,i.qr_mode detail,
                     COALESCE(b.name,'PUSAT') branch_name,COALESCE(u.full_name,u.username,'Belum terhubung') operator_name
                     FROM branch_qr_payment_intents i LEFT JOIN users u ON u.id=i.operator_user_id LEFT JOIN koperasi_branches b ON b.id=i.branch_id
                     WHERE i.id=? AND i.member_id=? AND i.status='PAID' ''',[record_id,member['id']])
    elif source=='KODE_3D':
        row=q_one('''SELECT p.payment_no reference_no,p.created_at paid_at,p.amount,'WALLET' method,p.cashier_session_id,'Kode 3 digit: '||p.code detail,
                     COALESCE(b.name,'PUSAT') branch_name,COALESCE(u.full_name,u.username,'Belum terhubung') operator_name
                     FROM branch_code_payments p LEFT JOIN users u ON u.id=p.operator_user_id LEFT JOIN koperasi_branches b ON b.id=p.branch_id
                     WHERE p.id=? AND p.member_id=? AND p.status='PAID' ''',[record_id,member['id']])
    if not row: return ('Struk tidak ditemukan atau bukan milik akun ini.',404)
    body=render_template_string(r'''<div class="digital-receipt"><section class="dr-paper"><header><span>KOPERASI CANTEEN</span><h2>STRUK PEMBAYARAN</h2><p>{{row.branch_name}}</p></header><div class="dr-dashed"></div><dl><div><dt>Referensi</dt><dd>{{row.reference_no}}</dd></div><div><dt>Waktu</dt><dd>{{row.paid_at}}</dd></div><div><dt>Metode</dt><dd>{{receipt_source}} · {{row.method}}</dd></div><div><dt>Detail</dt><dd>{{row.detail}}</dd></div><div><dt>Anggota</dt><dd>{{member.name}}</dd></div><div><dt>Operator</dt><dd>{{row.operator_name}}</dd></div><div><dt>Sesi Operator</dt><dd>#{{row.cashier_session_id or '-'}}</dd></div></dl><div class="dr-dashed"></div><div class="dr-total"><span>TOTAL DIBAYAR</span><strong>{{rupiah(row.amount)}}</strong></div><footer><i>✓</i><b>PEMBAYARAN BERHASIL</b><small>Struk digital ini tersimpan di akun anggota.</small></footer></section><div class="dr-actions"><button type="button" onclick="window.print()">Cetak / Simpan PDF</button><a href="{{url_for('member_purchases')}}">Kembali ke Riwayat</a></div></div>''',row=row,member=member,receipt_source=source,rupiah=rupiah)
    return render_page('Struk Pembayaran',body)

