@app.route('/api/branch/live-payments')
@login_required
@role_required('admin','kasir','branch_admin','branch_cashier')
def api_branch_live_payments():
    ensure_branch_qr_payment_schema(); ensure_payment_code_schema()
    bid=get_branch_id()
    qr=q_all('''SELECT i.id,i.payment_code,i.amount,i.paid_at,COALESCE(m.name,'Anggota') member_name FROM branch_qr_payment_intents i LEFT JOIN members m ON m.id=i.member_id WHERE i.branch_id=? AND i.status='PAID' ORDER BY i.paid_at DESC,i.id DESC LIMIT 50''',[bid])
    items=[{'id':r['id'],'payment_code':r['payment_code'],'amount':r['amount'],'amount_text':rupiah(r['amount']),'paid_at':r['paid_at'],'member_name':r['member_name'],'source':'QR'} for r in qr]
    return jsonify({'ok':True,'items':items,'server_time':now_str()})

@app.route('/api/cashier/qr-payment/status')
@login_required
@role_required('admin','kasir','branch_admin','branch_cashier')
def api_cashier_qr_status():
    bid=get_branch_id(); after=request.args.get('after',0,type=int)
    active=q_one('''SELECT i.*,COALESCE(m.name,'') member_name FROM branch_qr_payment_intents i LEFT JOIN members m ON m.id=i.member_id WHERE i.branch_id=? AND i.operator_user_id=? ORDER BY i.id DESC LIMIT 1''',[bid,cashier_operator_id()])
    paid=q_all('''SELECT i.id,i.payment_code,i.amount,i.paid_at,COALESCE(m.name,'') member_name FROM branch_qr_payment_intents i LEFT JOIN members m ON m.id=i.member_id WHERE i.branch_id=? AND i.status='PAID' AND i.id>? ORDER BY i.id''',[bid,after])
    latest=q_one('SELECT COALESCE(MAX(id),0) id FROM branch_qr_payment_intents WHERE branch_id=?',[bid])['id']
    return jsonify({'ok':True,'latest_id':latest,'active':dict(active) if active else None,'new_paid':[dict(x) for x in paid]})

@app.route('/pay/branch/<token>',methods=['GET','POST'])
@login_required
def branch_qr_pay(token):
    ensure_branch_qr_payment_schema(); profile=q_one('SELECT * FROM branch_qr_profiles WHERE qr_token=? AND is_active=1',[token])
    if not profile: return ('QR cabang tidak valid atau sudah dinonaktifkan.',404)
    member=current_wallet_member()
    if not member:
        flash('QR pembayaran hanya dapat digunakan oleh akun anggota yang terhubung ke wallet.','error'); return redirect(url_for('dashboard'))
    bid=profile['branch_id']; branch_name=get_branch_name(bid)
    # Expire stale intents before display.
    exec_sql("UPDATE branch_qr_payment_intents SET status='EXPIRED',cancelled_at=? WHERE branch_id=? AND status='WAITING' AND expires_at<?",[now_str(),bid,now_str()])
    intent=q_one("SELECT * FROM branch_qr_payment_intents WHERE branch_id=? AND status='WAITING' ORDER BY id DESC LIMIT 1",[bid])
    balance=wallet_balance(member['id']) if 'wallet_balance' in globals() else q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END),0) saldo FROM saldo_history WHERE member_id=?',[member['id']])['saldo']
    if request.method=='POST':
        iid=int(request.form.get('intent_id') or 0)
        direct_amount=parse_float(request.form.get('direct_amount'),0)
        conn=get_conn()
        try:
            conn.execute('BEGIN IMMEDIATE')
            if iid<=0:
                if direct_amount<1000: raise ValueError('Nominal minimal Rp1.000.')
                paycode='QRS-'+datetime.now().strftime('%Y%m%d%H%M%S')+'-'+os.urandom(3).hex().upper()
                expires=(datetime.now()+timedelta(minutes=10)).strftime('%Y-%m-%d %H:%M:%S')
                resolved_operator,resolved_session=resolve_branch_payment_operator(bid)
                cur=conn.execute('''INSERT INTO branch_qr_payment_intents(payment_code,branch_id,amount,status,note,operator_user_id,cashier_session_id,created_at,expires_at,qr_mode) VALUES(?,?,?,'WAITING','Pembayaran langsung QR statis',?,?,?,?,'STATIC_DIRECT')''',[paycode,bid,direct_amount,resolved_operator,resolved_session,now_str(),expires])
                iid=cur.lastrowid
            locked=conn.execute("SELECT * FROM branch_qr_payment_intents WHERE id=? AND branch_id=? AND status='WAITING'",[iid,bid]).fetchone()
            if not locked: raise ValueError('Tagihan sudah dibayar, dibatalkan, atau kedaluwarsa.')
            if locked['expires_at'] and locked['expires_at']<now_str(): raise ValueError('Tagihan sudah kedaluwarsa.')
            saldo=conn.execute('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END),0) saldo FROM saldo_history WHERE member_id=?',[member['id']]).fetchone()['saldo'] or 0
            amount=float(locked['amount'] or 0)
            if float(saldo)<amount: raise ValueError(f'Saldo wallet tidak cukup. Saldo tersedia {rupiah(saldo)}.')
            after=float(saldo)-amount
            resolved_operator=locked['operator_user_id']; resolved_session=locked['cashier_session_id']
            if not resolved_operator or not resolved_session:
                resolved_operator,resolved_session=resolve_branch_payment_operator(bid)
                conn.execute('UPDATE branch_qr_payment_intents SET operator_user_id=?,cashier_session_id=? WHERE id=?',[resolved_operator,resolved_session,iid])
            touch_payment_operator_session(conn,resolved_operator,resolved_session)
            conn.execute('INSERT INTO saldo_history(member_id,tipe,nominal,saldo_sebelum,saldo_setelah,keterangan,reference_id,created_by) VALUES(?,"KELUAR",?,?,?,?,?,?)',[member['id'],amount,saldo,after,f'QR Payment {branch_name} - {locked["payment_code"]}',iid,session.get('user_id')])
            changed=conn.execute("UPDATE branch_qr_payment_intents SET status='PAID',member_id=?,wallet_account_no=(SELECT account_no FROM wallet_accounts WHERE member_id=?),paid_at=? WHERE id=? AND status='WAITING'",[member['id'],member['id'],now_str(),iid]).rowcount
            if changed!=1: raise ValueError('Pembayaran diproses pihak lain. Saldo tidak dikurangi.')
            conn.execute('INSERT INTO branch_qr_payment_events(intent_id,branch_id,event_type,event_at,user_id,member_id,ip_address,detail) VALUES(?,?,?,?,?,?,?,?)',[iid,bid,'PAID',now_str(),session.get('user_id'),member['id'],request.remote_addr or '',f'Saldo sebelum={saldo}; sesudah={after}'])
            conn.commit(); log_action('BRANCH_QR_PAID','branch_qr_payment_intents',iid,f'{branch_name}; member={member["id"]}; amount={amount}')
            flash(f'Pembayaran {rupiah(amount)} ke {branch_name} berhasil.','success'); return redirect(url_for('branch_qr_pay',token=token,success=iid))
        except Exception as e:
            conn.rollback(); flash(str(e),'error')
        finally: conn.close()
        return redirect(url_for('branch_qr_pay',token=token))
    success=request.args.get('success',type=int); paid=q_one('SELECT * FROM branch_qr_payment_intents WHERE id=? AND member_id=? AND status="PAID"',[success,member['id']]) if success else None
    body=render_template_string(r'''<div class="member-qr-pay"><header><span>SCAN TO PAY</span><h2>{{branch_name}}</h2><p>Pembayaran langsung dari saldo Koperasi Wallet.</p></header>{% if paid %}<section class="member-pay-success"><i>✓</i><h3>Pembayaran Berhasil</h3><b>{{rupiah(paid.amount)}}</b><small>{{paid.payment_code}} · {{paid.paid_at}}</small><a href="{{url_for('wallet')}}">Lihat Mutasi Wallet</a></section>{% elif intent %}<section class="member-pay-card"><div><span>TAGIHAN AKTIF</span><b>{{rupiah(intent.amount)}}</b><small>{{intent.payment_code}} · {{intent.note or 'Pembayaran koperasi'}}</small></div><div class="member-pay-balance"><span>Saldo Anda</span><b>{{rupiah(balance)}}</b></div><form method="post"><input type="hidden" name="intent_id" value="{{intent.id}}"><button class="btn-success" {{'disabled' if balance<intent.amount else ''}} data-confirm="Bayar {{rupiah(intent.amount)}} ke {{branch_name}}?">Bayar Sekarang</button></form>{% if balance<intent.amount %}<p class="pay-insufficient">Saldo tidak cukup. Silakan isi saldo terlebih dahulu.</p>{% endif %}</section>{% else %}<section class="member-pay-card direct-static-pay"><div><span>QR STATIS CABANG</span><b>Masukkan Nominal</b><small>Konfirmasi nominal sesuai total yang disampaikan kasir.</small></div><div class="member-pay-balance"><span>Saldo Anda</span><b>{{rupiah(balance)}}</b></div><form method="post"><label>Nominal pembayaran<input type="number" name="direct_amount" min="1000" step="1000" placeholder="Rp 20.000" required autofocus></label><button class="btn-success" data-confirm="Lanjutkan pembayaran QR statis?">Lanjutkan Pembayaran</button></form></section>{% endif %}</div>''',branch_name=branch_name,intent=intent,balance=float(balance or 0),member=member,paid=paid,rupiah=rupiah)
    return render_page('Bayar QR Cabang',body)


@app.route('/admin/operator-payment-history')
@login_required
@role_required('admin','branch_admin','manager')
def admin_operator_payment_history():
    ensure_branch_qr_payment_schema(); ensure_payment_code_schema(); user=current_user(); bid=get_branch_id()
    # Backfill older payment rows when a matching operator session can be determined safely.
    conn=get_conn()
    try:
        pending=conn.execute("SELECT id,branch_id,paid_at FROM branch_qr_payment_intents WHERE status='PAID' AND cashier_session_id IS NULL AND paid_at IS NOT NULL").fetchall()
        for pay in pending:
            match=conn.execute('''SELECT id,operator_user_id FROM cashier_operator_sessions WHERE branch_id=? AND login_at<=? AND COALESCE(logout_at,?)>=? ORDER BY login_at DESC LIMIT 1''',[pay['branch_id'],pay['paid_at'],now_str(),pay['paid_at']]).fetchone()
            if match: conn.execute('UPDATE branch_qr_payment_intents SET operator_user_id=?,cashier_session_id=? WHERE id=?',[match['operator_user_id'],match['id'],pay['id']])
        pending=conn.execute("SELECT id,branch_id,created_at FROM branch_code_payments WHERE status='PAID' AND cashier_session_id IS NULL").fetchall()
        for pay in pending:
            match=conn.execute('''SELECT id,operator_user_id FROM cashier_operator_sessions WHERE branch_id=? AND login_at<=? AND COALESCE(logout_at,?)>=? ORDER BY login_at DESC LIMIT 1''',[pay['branch_id'],pay['created_at'],now_str(),pay['created_at']]).fetchone()
            if match: conn.execute('UPDATE branch_code_payments SET operator_user_id=?,cashier_session_id=? WHERE id=?',[match['operator_user_id'],match['id'],pay['id']])
        conn.commit()
    finally: conn.close()
    start=request.args.get('start') or today_str(); end=request.args.get('end') or today_str(); params=[start+' 00:00:00',end+' 23:59:59']
    scope='';
    if user['role']=='branch_admin': scope=' AND x.branch_id=?'; params.append(bid)
    sql='''SELECT x.*,u.full_name operator_name,u.username operator_username,m.name member_name,b.name branch_name,cs.login_at session_login,cs.logout_at session_logout FROM (
      SELECT i.id source_id,'QR' source,i.payment_code reference_no,i.branch_id,i.operator_user_id,i.cashier_session_id,i.member_id,i.amount,i.status,i.created_at,i.paid_at,i.qr_mode mode
      FROM branch_qr_payment_intents i WHERE i.status='PAID'
      UNION ALL
      SELECT p.id source_id,'KODE_3D' source,p.payment_no reference_no,p.branch_id,p.operator_user_id,p.cashier_session_id,p.member_id,p.amount,p.status,p.created_at,p.created_at paid_at,'CODE' mode
      FROM branch_code_payments p WHERE p.status='PAID'
    ) x LEFT JOIN users u ON u.id=x.operator_user_id LEFT JOIN members m ON m.id=x.member_id LEFT JOIN koperasi_branches b ON b.id=x.branch_id LEFT JOIN cashier_operator_sessions cs ON cs.id=x.cashier_session_id
    WHERE x.paid_at BETWEEN ? AND ?'''+scope+' ORDER BY x.paid_at DESC LIMIT 1500'
    rows=q_all(sql,params)
    totals={'count':len(rows),'amount':sum(float(r['amount'] or 0) for r in rows),'unassigned':sum(1 for r in rows if not r['operator_user_id'])}
    body=render_template_string(r'''<div class="cash-admin"><header class="cash-admin-hero"><div><span>ADMIN PAYMENT AUDIT</span><h2>History Pembayaran Operator</h2><p>Semua pembayaran QR dan kode 3 digit tercatat pada operator, sesi kerja, anggota, serta cabang penerima.</p></div></header><section class="cash-admin-kpis"><article><span>Total Record</span><b>{{totals.count}}</b><small>Periode terpilih</small></article><article><span>Total Pembayaran</span><b>{{rupiah(totals.amount)}}</b><small>QR + kode 3 digit</small></article><article><span>Tanpa Operator</span><b>{{totals.unassigned}}</b><small>Perlu ditinjau</small></article></section><section class="cash-admin-card"><div class="cash-admin-head"><div><span>OPERATOR PAYMENT LEDGER</span><h3>Record Pembayaran</h3></div><form method="get" class="rotation-filter"><input type="date" name="start" value="{{start}}"><input type="date" name="end" value="{{end}}"><button>Terapkan</button></form></div><div class="table-wrap"><table><thead><tr><th>Waktu Bayar</th><th>Sumber</th><th>Referensi</th><th>Cabang</th><th>Operator</th><th>ID Sesi</th><th>Anggota</th><th>Nominal</th><th>Status</th></tr></thead><tbody>{% for r in rows %}<tr><td>{{r.paid_at}}</td><td><span class="badge badge-info">{{r.source}}</span></td><td><code>{{r.reference_no}}</code><small>{{r.mode}}</small></td><td>{{r.branch_name or 'PUSAT'}}</td><td><b>{{r.operator_name or r.operator_username or 'BELUM TERHUBUNG'}}</b></td><td>{{r.cashier_session_id or '-'}}</td><td>{{r.member_name or '-'}}</td><td><b>{{rupiah(r.amount)}}</b></td><td><span class="badge badge-success">{{r.status}}</span></td></tr>{% else %}<tr><td colspan="9" class="muted text-center">Belum ada pembayaran.</td></tr>{% endfor %}</tbody></table></div></section></div>''',rows=rows,totals=totals,start=start,end=end,rupiah=rupiah)
    return render_page('History Pembayaran Operator',body)

@app.route('/cashier/qr-payment/history')
@login_required
@role_required('admin','branch_admin','manager','kasir','branch_cashier')
def branch_qr_payment_history():
    ensure_branch_qr_payment_schema(); user=current_user(); bid=get_branch_id(); start=request.args.get('start') or today_str(); end=request.args.get('end') or today_str(); status=request.args.get('status',''); params=[start+' 00:00:00',end+' 23:59:59']
    sql='''SELECT i.*,COALESCE(b.name,'PUSAT') branch_name,COALESCE(m.name,'-') member_name,COALESCE(u.full_name,u.username,'-') operator_name FROM branch_qr_payment_intents i LEFT JOIN koperasi_branches b ON b.id=i.branch_id LEFT JOIN members m ON m.id=i.member_id LEFT JOIN users u ON u.id=i.operator_user_id WHERE i.created_at BETWEEN ? AND ?'''
    if user['role'] in ('branch_admin','branch_cashier','kasir'): sql+=' AND i.branch_id=?'; params.append(bid)
    if status: sql+=' AND i.status=?'; params.append(status)
    rows=q_all(sql+' ORDER BY i.id DESC LIMIT 1000',params)
    body=render_template_string(r'''<div class="branch-qr-suite"><header class="branch-qr-hero"><div><span>QR PAYMENT LEDGER</span><h2>Riwayat QR Payment</h2><p>Audit tagihan, pembayaran wallet, operator, anggota, cabang, dan waktu penyelesaian.</p></div></header><section class="branch-qr-history"><header><form method="get" class="qr-history-filter"><input type="date" name="start" value="{{start}}"><input type="date" name="end" value="{{end}}"><select name="status"><option value="">Semua status</option>{% for x in ['WAITING','PAID','CANCELLED','EXPIRED'] %}<option value="{{x}}" {{'selected' if status==x else ''}}>{{x}}</option>{% endfor %}</select><button>Terapkan</button></form></header><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Mode QR</th><th>Cabang</th><th>Operator</th><th>Sesi</th><th>Anggota</th><th>Nominal</th><th>Dibuat</th><th>Dibayar</th><th>Status</th></tr></thead><tbody>{% for r in rows %}<tr><td><code>{{r.payment_code}}</code></td><td><span class="badge badge-info">{{r.qr_mode or "STATIC"}}</span></td><td>{{r.branch_name}}</td><td>{{r.operator_name}}</td><td>{{r.cashier_session_id or "-"}}</td><td>{{r.member_name}}</td><td><b>{{rupiah(r.amount)}}</b></td><td>{{r.created_at}}</td><td>{{r.paid_at or '-'}}</td><td><span class="badge {{'badge-success' if r.status=='PAID' else 'badge-warn' if r.status=='WAITING' else 'badge-gray'}}">{{r.status}}</span></td></tr>{% else %}<tr><td colspan="10" class="muted text-center">Belum ada transaksi QR.</td></tr>{% endfor %}</tbody></table></div></section></div>''',rows=rows,start=start,end=end,status=status,rupiah=rupiah)
    return render_page('Riwayat QR Payment',body)

CSS_DESIGN += r'''
.branch-qr-suite{display:grid;gap:14px}.branch-qr-hero{position:relative;overflow:hidden;display:flex;justify-content:space-between;align-items:flex-end;min-height:185px;padding:25px;border-radius:18px;background:radial-gradient(circle at 82% 18%,rgba(37,99,235,.36),transparent 27%),linear-gradient(135deg,#06111d,#123b55);color:#fff;box-shadow:0 18px 45px rgba(6,17,29,.22)}.branch-qr-lines{position:absolute;inset:-40px -80px -50px 42%;background:repeating-radial-gradient(ellipse at 100% 10%,transparent 0 12px,rgba(103,232,249,.22) 13px 14px,transparent 15px 29px);animation:managerHairDrift 12s ease-in-out infinite alternate}.branch-qr-hero>div:not(.branch-qr-lines){position:relative;z-index:2}.branch-qr-hero span,.branch-qr-title span,.branch-qr-history header span{color:#67e8f9;font-size:8px;font-weight:950;letter-spacing:.17em}.branch-qr-hero h2{margin:7px 0;color:#fff;font-size:27px}.branch-qr-hero p{margin:0;max-width:670px;color:#b9cede;font-size:10px}.branch-qr-live{display:flex;align-items:center;gap:7px;padding:9px 12px;border:1px solid rgba(255,255,255,.16);border-radius:999px;background:rgba(255,255,255,.08);font-size:8px;font-weight:900}.branch-qr-live i{width:8px;height:8px;border-radius:50%;background:#5eead4;animation:adminPresencePulse 1.8s infinite}.branch-qr-grid{display:grid;grid-template-columns:380px minmax(0,1fr);gap:14px}.branch-qr-code,.branch-qr-terminal,.branch-qr-history{overflow:hidden;border:1px solid #d9e4ed;border-radius:15px;background:#fff;box-shadow:0 8px 24px rgba(15,35,52,.05)}.branch-qr-title,.branch-qr-history>header{display:flex;justify-content:space-between;align-items:center;padding:16px 18px;border-bottom:1px solid #e7edf2}.branch-qr-title span,.branch-qr-history header span{color:#0f9f97}.branch-qr-title h3,.branch-qr-history h3{margin:4px 0 0}.branch-qr-code>img{display:block;width:250px;height:250px;margin:22px auto 12px;padding:10px;border:1px solid #dfe8ef;border-radius:18px}.branch-qr-code>code{display:block;margin:0 16px;padding:9px;border-radius:8px;background:#f1f5f8;font-size:7px;overflow:hidden;text-overflow:ellipsis}.branch-qr-code>small{display:block;padding:10px 16px 17px;color:#8494a5;text-align:center}.qr-amount-form{display:grid;gap:13px;padding:22px}.qr-amount-form label{display:grid;gap:6px;font-size:9px;font-weight:800}.qr-amount-form input[type=number]{height:65px;font-size:27px;font-weight:900;text-align:center}.qr-active{position:relative;display:grid;place-items:center;min-height:330px;padding:25px;text-align:center;overflow:hidden}.qr-active>span{color:#0f9f97;font-size:8px;font-weight:950;letter-spacing:.15em}.qr-active>b{margin:10px 0;font-size:38px}.qr-active>small{color:#7d8d9c}.qr-radar{position:relative;width:115px;height:115px;margin:20px}.qr-radar:before,.qr-radar:after{content:'';position:absolute;inset:0;border:1px solid rgba(37,99,235,.18);border-radius:50%;animation:managerRingBreath 2.7s infinite}.qr-radar:after{inset:18px;animation-delay:-1s}.qr-radar i{position:absolute;left:50%;top:50%;width:12px;height:12px;border-radius:50%;background:#2dd4bf;transform:translate(-50%,-50%);box-shadow:0 0 0 7px rgba(45,212,191,.13),0 0 20px #2dd4bf}.qr-radar em{position:absolute;left:50%;top:50%;width:48%;height:1px;background:linear-gradient(90deg,#67e8f9,transparent);transform-origin:left;animation:managerSpin 2s linear infinite}.qr-paid-pop{display:grid;place-items:center;margin:0 20px 20px;padding:22px;border-radius:16px;background:#e8faf4;color:#087e6a}.qr-paid-pop i{display:grid;place-items:center;width:48px;height:48px;border-radius:50%;background:#10b981;color:#fff;font-size:24px;font-style:normal}.qr-paid-pop b,.qr-paid-pop strong,.qr-paid-pop small{display:block;margin-top:6px}.branch-qr-history>div>article{display:grid;grid-template-columns:10px minmax(0,1fr) auto 80px;gap:10px;align-items:center;padding:12px 17px;border-bottom:1px solid #edf2f6}.branch-qr-history article>i{width:8px;height:8px;border-radius:50%;background:#94a3b8}.branch-qr-history article>i.paid{background:#10b981;box-shadow:0 0 9px #10b981}.branch-qr-history article>i.waiting{background:#f59e0b}.branch-qr-history article b,.branch-qr-history article small{display:block}.branch-qr-history article small{color:#8494a5;font-size:8px}.qr-history-filter{display:flex;gap:7px;align-items:end}.member-qr-pay{display:grid;gap:14px;max-width:520px;margin:0 auto}.member-qr-pay>header{position:relative;overflow:hidden;padding:25px;border-radius:21px;background:linear-gradient(135deg,#06111d,#123b55);color:#fff}.member-qr-pay>header span{color:#67e8f9;font-size:8px;letter-spacing:.18em}.member-qr-pay>header h2{margin:7px 0;color:#fff}.member-qr-pay>header p{margin:0;color:#b9cede}.member-pay-card,.member-pay-success,.member-pay-wait{padding:24px;border:1px solid #d9e4ed;border-radius:20px;background:#fff;text-align:center;box-shadow:0 12px 35px rgba(15,35,52,.08)}.member-pay-card>div:first-child span,.member-pay-card>div:first-child b,.member-pay-card>div:first-child small{display:block}.member-pay-card>div:first-child span{color:#0f9f97;font-size:8px;font-weight:950}.member-pay-card>div:first-child b{margin:10px;font-size:36px}.member-pay-card>div:first-child small{color:#7d8d9c}.member-pay-balance{display:flex;justify-content:space-between;margin:22px 0;padding:13px;border-radius:12px;background:#f1f6f8}.member-pay-card button{width:100%}.member-pay-success i{display:grid;place-items:center;width:60px;height:60px;margin:auto;border-radius:50%;background:#10b981;color:#fff;font-size:30px;font-style:normal}.member-pay-success b{display:block;margin:12px;font-size:30px}.member-pay-success small,.member-pay-success a{display:block;margin-top:8px}.pay-insufficient{color:#b42335;font-size:9px}
@media(max-width:900px){.branch-qr-grid{grid-template-columns:1fr}.branch-qr-code>img{width:220px;height:220px}}
@media(max-width:768px){.branch-qr-suite{padding:0 12px}.branch-qr-hero{align-items:flex-start;flex-direction:column;min-height:210px;padding:20px;border-radius:22px}.branch-qr-hero h2{font-size:23px}.branch-qr-lines{inset:0 -180px 0 10%}.branch-qr-code,.branch-qr-terminal,.branch-qr-history{border-radius:20px}.qr-active{min-height:300px}.qr-active>b{font-size:31px}.branch-qr-history>div>article{grid-template-columns:8px minmax(0,1fr) auto}.branch-qr-history article>span{display:none}.qr-history-filter{display:grid;grid-template-columns:1fr 1fr;width:100%}.qr-history-filter select,.qr-history-filter button{grid-column:1/-1}.member-qr-pay{padding:0 12px}.member-pay-card>div:first-child b{font-size:30px}}
'''

@app.route('/quick-cashier', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'kasir', 'branch_admin', 'branch_cashier')
def quick_cashier():
    user=current_user()
    blocked=require_branch_for_branch_role(user)
    if blocked: return blocked
    if request.method == 'POST':
        total = parse_float(request.form.get('total', 0) or 0)
        paid = parse_float(request.form.get('paid', 0) or 0)
        payment_method = request.form.get('payment_method', 'tunai')
        member_id = request.form.get('member_id') or None
        customer_name = request.form.get('customer_name', '').strip()
        note = request.form.get('note', '').strip()
        invoice = gen_code('INV')
        if total <= 0:
            flash('Total belanja harus lebih dari 0.', 'error')
            return redirect(url_for('quick_cashier'))
        change_amount = 0
        if payment_method == 'tunai':
            if paid < total:
                flash(f'Nominal bayar kurang. Total {rupiah(total)}', 'error')
                return redirect(url_for('quick_cashier'))
            change_amount = paid - total
        elif payment_method == 'wallet':
            if not member_id:
                flash('Bayar wallet wajib pilih member.', 'error')
                return redirect(url_for('quick_cashier'))
            member_saldo = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id=?', [member_id])['saldo']
            if member_saldo < total:
                flash(f'Saldo wallet tidak cukup. Saldo: {rupiah(member_saldo)}', 'error')
                return redirect(url_for('quick_cashier'))
            saldo_sebelum = member_saldo
            saldo_setelah = saldo_sebelum - total
            exec_sql('INSERT INTO saldo_history(member_id, tipe, nominal, saldo_sebelum, saldo_setelah, keterangan, reference_id, created_by) VALUES (?, "KELUAR", ?, ?, ?, "Pembayaran quick cashier", ?, ?)',
                [member_id, total, saldo_sebelum, saldo_setelah, 0, session.get('user_id')])
            paid = total
        else:
            paid = total
        # Simpan ke antrian verifikasi (PENDING) — stok belum dikurangi
        cashier_branch_id = get_branch_id()
        qid = exec_sql('INSERT INTO quick_cashier_queue(invoice_no,trx_date,total,payment_method,member_id,customer_name,note,status,created_by,stock_branch_id,cashier_session_id,paid,change_amount) VALUES(?,?,?,?,?,?,?,"PENDING",?,?,?,?,?)',
            [invoice,today_str(),total,payment_method,member_id,customer_name,note,cashier_operator_id(),cashier_branch_id,cashier_operator_session_id(),paid,change_amount])
        log_action('QUICK_CASHIER_PENDING', 'quick_cashier_queue', qid, f'Total {total} metode {payment_method} — menunggu verifikasi')
        flash(f'✅ Transaksi antri verifikasi! Invoice: {invoice} — {rupiah(total)}. Status: PENDING. Admin akan verifikasi untuk kurangi stok.', 'success')
        return redirect(url_for('quick_cashier'))
    members_rows = q_all("SELECT id, member_code, name FROM members WHERE status='Aktif' ORDER BY name ASC")
    cashier_branch_name = get_branch_name(get_branch_id())
    body = render_template_string('''
    <div class="sales-suite quick-suite">
      <header class="sales-hero"><div><span>POINT OF SALE</span><h2>Kasir Cepat</h2><p>Catat pembayaran untuk lokasi <b>{{cashier_branch_name}}</b>. Transaksi terkunci ke persediaan lokasi kasir sebelum stok diverifikasi.</p></div><div class="sales-hero-chip"><small>Mode transaksi</small><b>Input nominal cepat</b></div></header>
      <div class="grid sales-main-grid">
        <div class="col-6">
            <div class="card" style="text-align:center;">
                <h2>⚡ Quick Cashier</h2>
                <div class="muted small">Input total belanja langsung — tanpa scan barang 1 per 1. Stok dikurangi nanti.</div>
                <hr>
                <form method="post" id="quickForm">
                    <div class="form-group" style="text-align:left;">
                        <label>Member (opsional)</label>
                        <select name="member_id">
                            <option value="">🏷️ Umum</option>
                            {% for m in members_rows %}
                            <option value="{{ m['id'] }}">{{ m['member_code'] }} — {{ m['name'] }}</option>
                            {% endfor %}
                        </select>
                    </div>
                    <div class="form-group" style="text-align:left;">
                        <label>Nama Pelanggan (opsional)</label>
                        <input name="customer_name" placeholder="Nama pelanggan">
                    </div>
                    <div style="display:flex;gap:16px;align-items:center;justify-content:center;margin:24px 0;">
                        <div style="font-size:14px;color:var(--text-muted);">Total Belanja</div>
                        <div style="font-size:48px;font-weight:800;color:#059669;" id="totalDisplay">Rp 0</div>
                    </div>
                    <input type="hidden" name="total" id="totalInput" value="0">
                    <div class="keypad" style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;max-width:320px;margin:0 auto;">
                        <button type="button" class="btn btn-ghost" onclick="press('1')" style="font-size:24px;padding:16px;">1</button>
                        <button type="button" class="btn btn-ghost" onclick="press('2')" style="font-size:24px;padding:16px;">2</button>
                        <button type="button" class="btn btn-ghost" onclick="press('3')" style="font-size:24px;padding:16px;">3</button>
                        <button type="button" class="btn btn-ghost" onclick="press('4')" style="font-size:24px;padding:16px;">4</button>
                        <button type="button" class="btn btn-ghost" onclick="press('5')" style="font-size:24px;padding:16px;">5</button>
                        <button type="button" class="btn btn-ghost" onclick="press('6')" style="font-size:24px;padding:16px;">6</button>
                        <button type="button" class="btn btn-ghost" onclick="press('7')" style="font-size:24px;padding:16px;">7</button>
                        <button type="button" class="btn btn-ghost" onclick="press('8')" style="font-size:24px;padding:16px;">8</button>
                        <button type="button" class="btn btn-ghost" onclick="press('9')" style="font-size:24px;padding:16px;">9</button>
                        <button type="button" class="btn btn-ghost" onclick="press('00')" style="font-size:24px;padding:16px;">00</button>
                        <button type="button" class="btn btn-ghost" onclick="press('0')" style="font-size:24px;padding:16px;">0</button>
                        <button type="button" class="btn btn-ghost" onclick="pressDel()" style="font-size:24px;padding:16px;">⌫</button>
                    </div>
                    <hr>
                    <div class="form-group" style="text-align:left;">
                        <label>Pilih Metode Pembayaran</label>
                        <div style="display:flex;gap:12px;flex-wrap:wrap;">
                            <label class="btn btn-ghost" style="flex:1;cursor:pointer;padding:12px;">
                                <input type="radio" name="payment_method" value="tunai" checked onchange="toggleMethod()"> 💰 Tunai
                            </label>
                            <label class="btn btn-ghost" style="flex:1;cursor:pointer;padding:12px;">
                                <input type="radio" name="payment_method" value="wallet" onchange="toggleMethod()"> 💳 Wallet
                            </label>
                        </div>
                    </div>
                    <div class="form-group" id="paidSection" style="text-align:left;">
                        <label>💰 Uang Dibayar</label>
                        <div class="login-input-wrap">
                            <span class="login-input-icon">💵</span>
                            <input type="number" id="paidInput" name="paid" min="0" placeholder="Jumlah uang" style="font-size:20px;font-weight:700;padding:14px 14px 14px 42px;">
                        </div>
                        <div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;">
                            <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(parseInt(document.getElementById('totalInput').value)||0)">Uang Pas</button>
                            <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(Math.ceil((parseInt(document.getElementById('totalInput').value)||0)/1000)*1000+5000)">+5rb</button>
                            <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(Math.ceil((parseInt(document.getElementById('totalInput').value)||0)/10000)*10000)">+10rb</button>
                            <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(Math.ceil((parseInt(document.getElementById('totalInput').value)||0)/50000)*50000)">+50rb</button>
                            <div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;border-top:1px solid var(--border);padding-top:8px;">
                                <span class="small muted">Simpanan nominal:</span>
                                <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(50000)">50rb</button>
                                <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(100000)">100rb</button>
                                <button type="button" class="btn btn-sm btn-ghost" onclick="setPaid(200000)">200rb</button>
                                <button type="button" class="btn btn-sm btn-ghost" onclick="saveCustom()">💾 Simpan nominal</button>
                                <input type="number" id="customSaveAmount" placeholder="Nominal" style="width:100px;font-size:12px;padding:6px 10px;">
                                <button type="button" class="btn btn-sm btn-ghost" id="savedBtn" style="display:none;" onclick="setPaid(parseInt(this.dataset.val)||0)">💾 <span id="savedLabel"></span></button>
                            </div>
                        </div>
                    </div>
                    <div class="form-group" style="text-align:left;">
                        <label>Catatan</label>
                        <textarea name="note" style="min-height:40px;" placeholder="Catatan (opsional)"></textarea>
                    </div>
                    <button type="submit" class="btn-success" style="font-size:18px;padding:16px;">💾 Simpan Transaksi</button>
                </form>
            </div>
        </div>
        <div class="col-6">
            <div class="card" id="paymentInfo">
                <h2>💰 Ringkasan</h2>
                <div style="padding:20px;text-align:center;">
                    <div class="muted small">Total Belanja</div>
                    <div style="font-size:42px;font-weight:800;color:#059669;" id="ringkasanTotal">Rp 0</div>
                    <hr>
                    <div class="muted small">Uang Dibayar</div>
                    <div style="font-size:32px;font-weight:700;color:#2563eb;" id="ringkasanBayar">Rp 0</div>
                    <hr>
                    <div class="muted small">Kembalian</div>
                    <div style="font-size:36px;font-weight:800;" id="ringkasanKembali">Rp 0</div>
                </div>
            </div>
            <div class="card">
                <h2>📌 Panduan</h2>
                <ol style="font-size:13px;line-height:2;">
                    <li><strong>Input total</strong> belanja menggunakan keypad</li>
                    <li>Pilih <strong>metode bayar</strong> (Tunai / Wallet)</li>
                    <li>Masukkan <strong>uang dibayar</strong> (atau tekan "Uang Pas")</li>
                    <li>Klik <strong>Simpan Transaksi</strong></li>
                    <li>Setelah antrian selesai, lakukan <strong>Adjustment Stok</strong> untuk mengurangi barang</li>
                </ol>
            </div>
        </div>
      </div>
    </div>
    <script>
    function press(n){ var inp=document.getElementById('totalInput'); var v=inp.value.replace(/[^0-9]/g,''); v=v+n; inp.value=v.replace(/^0+/,'')||'0'; updateDisplay(); }
    function pressDel(){ var inp=document.getElementById('totalInput'); var v=inp.value.replace(/[^0-9]/g,''); v=v.slice(0,-1)||'0'; inp.value=v; updateDisplay(); }
    function updateDisplay(){
        var v=parseInt(document.getElementById('totalInput').value)||0;
        document.getElementById('totalDisplay').textContent='Rp '+v.toLocaleString('id-ID');
        document.getElementById('ringkasanTotal').textContent='Rp '+v.toLocaleString('id-ID');
        hitungKembalian();
    }
    function setPaid(v){ document.getElementById('paidInput').value=v; hitungKembalian(); }
    function hitungKembalian(){
        var total=parseInt(document.getElementById('totalInput').value)||0;
        var paid=parseFloat(document.getElementById('paidInput').value)||0;
        if(paid>0){document.getElementById('ringkasanBayar').textContent='Rp '+paid.toLocaleString('id-ID');}
        var kembali=paid-total; if(kembali<0)kembali=0;
        document.getElementById('ringkasanKembali').textContent='Rp '+kembali.toLocaleString('id-ID');
        document.getElementById('ringkasanKembali').style.color=kembali>=0?'#059669':'#ef4444';
    }
    function toggleMethod(){
        var pw=document.querySelector('input[name="payment_method"]:checked').value;
        document.getElementById('paidSection').style.display=pw==='wallet'?'none':'block';
        if(pw==='wallet'){document.getElementById('paidInput').value=document.getElementById('totalInput').value;hitungKembalian();}
    }
    document.getElementById('paidInput').addEventListener('input',hitungKembalian);
    </script>
    ''', members_rows=members_rows, total=0, rupiah=rupiah, cashier_branch_name=cashier_branch_name)
    return render_page('Kasir Cepat', cashier_operator_banner()+body)

# =========================
# Quick Cashier Queue — Verifikasi Admin untuk Kurangi Stok
# =========================
CSS_DESIGN += r"""
.qcq-shell{display:grid;gap:14px}.qcq-hero{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;padding:26px 28px;border-radius:14px;background:linear-gradient(125deg,#101828,#213b59);color:#fff;box-shadow:0 12px 30px rgba(16,24,40,.14)}.qcq-hero span{color:#f4a184;font-size:9px;font-weight:900;letter-spacing:.16em}.qcq-hero h2{margin:5px 0;color:#fff;font-size:26px}.qcq-hero p{color:#c5cfdb;font-size:11px}.qcq-hero .btn{background:#fff!important;color:#1c2c40!important}.qcq-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.qcq-kpis>div{padding:16px 18px;border:1px solid #d0d5dd;border-top:3px solid #2457d6;border-radius:10px;background:#fff}.qcq-kpis>div:nth-child(1){border-top-color:#e35d34}.qcq-kpis>div:nth-child(3){border-top-color:#087e6a}.qcq-kpis>div:nth-child(4){border-top-color:#b42335}.qcq-kpis span,.qcq-kpis b{display:block}.qcq-kpis span{color:#667085;font-size:8px;font-weight:850;text-transform:uppercase}.qcq-kpis b{margin-top:7px;font-size:20px}.qcq-filters{display:grid;grid-template-columns:minmax(260px,1fr) 190px 150px auto;gap:8px;padding:12px;border:1px solid #d0d5dd;border-radius:10px;background:#fff}.qcq-shell .card{border-radius:11px!important}.qcq-shell .card h3{font-size:15px!important}.qcq-shell .table-wrap{border-radius:9px!important}.qcq-shell td strong{color:#101828}.qcq-pager{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:13px 2px 0}.qcq-pager>span{color:#667085;font-size:9px}.qcq-pager>div{display:flex;align-items:center;gap:5px}.qcq-page{display:grid;place-items:center;min-width:32px;height:32px;border:1px solid #d0d5dd;border-radius:7px;background:#fff;color:#344054;font-size:10px;font-weight:800}.qcq-page.active{border-color:#2457d6;background:#2457d6;color:#fff}.qcq-pager .disabled{pointer-events:none;opacity:.4}
@media(max-width:900px){.qcq-kpis{grid-template-columns:repeat(2,1fr)}.qcq-filters{grid-template-columns:1fr 1fr}.qcq-filters input{grid-column:1/-1}}
@media(max-width:768px){.qcq-shell{padding:0 12px}.qcq-hero{align-items:flex-start;flex-direction:column;padding:20px;border-radius:20px}.qcq-hero h2{font-size:22px}.qcq-kpis{padding:0!important}.qcq-filters{grid-template-columns:1fr}.qcq-filters input{grid-column:auto}.qcq-shell .grid{gap:0!important}.qcq-shell .card{margin-left:0!important;margin-right:0!important}.qcq-pager{align-items:stretch;flex-direction:column}.qcq-pager>div{overflow-x:auto;padding-bottom:3px}}
"""

@app.route('/quick-cashier/queue', methods=['GET', 'POST'])
@login_required
@role_required('admin','branch_admin','kasir','branch_cashier')
def quick_cashier_queue():
    queue_user=current_user(); active_op=active_cashier_operator(); queue_branch_id=get_branch_id()
    if queue_user['role'] in ('kasir','branch_cashier'):
        if not active_op:
            flash('Login Operator aktif diperlukan untuk verifikasi Quick Control.','warning'); return redirect(url_for('cashier_operator_login',next=url_for('quick_cashier_queue')))
        queue_branch_id=active_op['branch_id']
        if not queue_branch_id:
            flash('Operator belum terikat ke cabang aktif.','error'); return redirect(url_for('dashboard'))
    if request.method == 'POST':
        qid = int(request.form.get('qid'))
        action = request.form.get('action')
        queue = q_one('SELECT * FROM quick_cashier_queue WHERE id = ? AND status = "PENDING"', [qid])
        if queue and current_user()['role']=='branch_admin':
            current_bid=get_branch_id()
            if (queue['stock_branch_id'] or None)!=(current_bid or None): queue=None
        if not queue:
            flash('Antrian tidak ditemukan, berbeda cabang, atau sudah diproses.', 'error')
            return redirect(url_for('quick_cashier_queue'))
        
        if action == 'reject':
            # Jika bayar wallet, refund saldo
            if queue['payment_method'] == 'wallet' and queue['member_id']:
                member_saldo = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id=?', [queue['member_id']])['saldo']
                new_saldo = member_saldo + queue['total']
                exec_sql('INSERT INTO saldo_history(member_id, tipe, nominal, saldo_sebelum, saldo_setelah, keterangan, reference_id, created_by) VALUES (?, "MASUK", ?, ?, ?, "Refund quick cashier ditolak", ?, ?)',
                    [queue['member_id'], queue['total'], member_saldo, new_saldo, qid, session.get('user_id')])
                flash(f'💰 Saldo wallet dikembalikan Rp {queue["total"]}', 'success')
            
            exec_sql('UPDATE quick_cashier_queue SET status = "REJECTED", verified_by = ?, verified_at = ? WHERE id = ?',
                [session.get('user_id'), now_str(), qid])
            log_action('QUICK_CASHIER_REJECTED', 'quick_cashier_queue', qid, f'Ditolak: {queue["invoice_no"]}')
            flash(f'❌ Transaksi {queue["invoice_no"]} ditolak.', 'warning')
        
        return redirect(url_for('quick_cashier_queue'))
    
    # Pagination terpisah untuk tabel pending dan riwayat.
    queue_scope=''; queue_scope_params=[]
    if queue_user['role'] in ('branch_admin','kasir','branch_cashier'):
        if queue_branch_id: queue_scope=' AND q.stock_branch_id=?'; queue_scope_params=[queue_branch_id]
        else: queue_scope=' AND q.stock_branch_id IS NULL'
    p_page = max(1, request.args.get('p_page', 1, type=int))
    h_page = max(1, request.args.get('h_page', 1, type=int))
    per_page = request.args.get('per_page', 10, type=int)
    per_page = per_page if per_page in (10, 20, 50) else 10
    keyword = (request.args.get('q') or '').strip()
    status_filter = (request.args.get('status') or '').strip().upper()
    pending_sql = """SELECT q.*, u.full_name creator_name, m.member_code, m.name member_name FROM quick_cashier_queue q LEFT JOIN users u ON u.id=q.created_by LEFT JOIN members m ON m.id=q.member_id WHERE q.status="PENDING" AND COALESCE(q.supervisor_review_status,'WAITING') IN ('WAITING','REVISION')"""
    pending_params = list(queue_scope_params)
    pending_sql += queue_scope
    if keyword:
        pending_sql += ' AND (q.invoice_no LIKE ? OR COALESCE(m.name,"") LIKE ? OR COALESCE(u.full_name,"") LIKE ?)'
        pending_params += [f'%{keyword}%'] * 3
    pending_sql += ' ORDER BY q.id ASC'
    pending = paginate_query(pending_sql, pending_params, p_page, per_page)
    history_sql = 'SELECT q.*, u.full_name creator_name, vu.full_name verifier_name, m.name member_name FROM quick_cashier_queue q LEFT JOIN users u ON u.id=q.created_by LEFT JOIN users vu ON vu.id=q.verified_by LEFT JOIN members m ON m.id=q.member_id WHERE q.status<>"PENDING"'
    history_params = list(queue_scope_params)
    history_sql += queue_scope
    if keyword:
        history_sql += ' AND (q.invoice_no LIKE ? OR COALESCE(m.name,"") LIKE ? OR COALESCE(u.full_name,"") LIKE ? OR COALESCE(vu.full_name,"") LIKE ?)'
        history_params += [f'%{keyword}%'] * 4
    if status_filter in ('VERIFIED','REJECTED','OPERATOR_VERIFIED','REVISION'):
        history_sql += ' AND q.status=?'; history_params.append(status_filter)
    history_sql += ' ORDER BY q.id DESC'
    verified = paginate_query(history_sql, history_params, h_page, per_page)
    if queue_user['role'] in ('branch_admin','kasir','branch_cashier'):
        if queue_branch_id:
            stats=q_one("""SELECT SUM(status='PENDING') pending_count,SUM(status='VERIFIED') verified_count,SUM(status='REJECTED') rejected_count,COALESCE(SUM(CASE WHEN status='PENDING' THEN total ELSE 0 END),0) pending_value FROM quick_cashier_queue WHERE stock_branch_id=?""",[queue_branch_id])
        else:
            stats=q_one("""SELECT SUM(status='PENDING') pending_count,SUM(status='VERIFIED') verified_count,SUM(status='REJECTED') rejected_count,COALESCE(SUM(CASE WHEN status='PENDING' THEN total ELSE 0 END),0) pending_value FROM quick_cashier_queue WHERE stock_branch_id IS NULL""")
    else:
        stats=q_one("""SELECT SUM(status='PENDING') pending_count,SUM(status='VERIFIED') verified_count,SUM(status='REJECTED') rejected_count,COALESCE(SUM(CASE WHEN status='PENDING' THEN total ELSE 0 END),0) pending_value FROM quick_cashier_queue""")
    
    body = render_template_string('''
    <div class="qcq-shell">
    <header class="qcq-hero"><div><span>QUICK CASHIER CONTROL</span><h2>Antrian Verifikasi</h2><p>{% if active_op %}Operator {{active_op.full_name or active_op.username}} · Cabang {{active_op.branch_name}}. {% endif %}Periksa transaksi cabang lalu kirim kepada Supervisor.</p></div><a class="btn btn-ghost" href="{{url_for('quick_cashier')}}">Buka Quick Cashier</a></header>
    <div class="qcq-kpis"><div><span>Menunggu</span><b>{{stats.pending_count or 0}}</b></div><div><span>Nilai Antrian</span><b>{{rupiah(stats.pending_value)}}</b></div><div><span>Terverifikasi</span><b>{{stats.verified_count or 0}}</b></div><div><span>Ditolak</span><b>{{stats.rejected_count or 0}}</b></div></div>
    <form method="get" class="qcq-filters"><input name="q" value="{{keyword}}" placeholder="Cari invoice, member, kasir"><select name="status"><option value="">Semua status riwayat</option><option value="VERIFIED" {{'selected' if status_filter=='VERIFIED' else ''}}>Terverifikasi</option><option value="REJECTED" {{'selected' if status_filter=='REJECTED' else ''}}>Ditolak</option></select><select name="per_page"><option value="10" {{'selected' if per_page==10 else ''}}>10 per halaman</option><option value="20" {{'selected' if per_page==20 else ''}}>20 per halaman</option><option value="50" {{'selected' if per_page==50 else ''}}>50 per halaman</option></select><button class="btn btn-ghost">Terapkan</button></form>
    <div class="grid">
        <div class="col-12">
            <div class="card" style="border-left:4px solid #f59e0b;">
                <h3>⏳ Menunggu Verifikasi ({{ pending.total }})</h3>
                <div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Tanggal</th><th>Total</th><th>Metode</th><th>Member</th><th>Kasir</th><th>Aksi</th></tr></thead>
                <tbody>
                {% for q in pending.rows %}
                <tr>
                    <td><strong>{{ q.invoice_no }}</strong></td>
                    <td>{{ q.trx_date }}</td>
                    <td style="font-weight:700;color:#2563eb;">{{ rupiah(q.total) }}</td>
                    <td><span class="badge {{ 'badge-success' if q.payment_method == 'tunai' else 'badge-info' }}">{{ q.payment_method }}</span></td>
                    <td>{{ q.member_name or 'Umum' }}</td>
                    <td>{{ q.creator_name or '-' }}</td>
                    <td>
                        <div style="display:flex;gap:6px;flex-wrap:wrap;">
                            <a href="/quick-cashier/verify/{{ q.id }}" class="btn btn-sm btn-success">✓ Periksa & Kirim Supervisor</a>
                            {% if queue_user.role in ['admin','branch_admin'] %}<form method="POST" style="display:inline;"><input type="hidden" name="qid" value="{{ q.id }}"><button name="action" value="reject" class="btn-sm btn-danger" data-confirm="Yakin tolak transaksi ini?">Tolak</button></form>{% endif %}
                        </div>
                    </td>
                </tr>
                {% else %}
                <tr><td colspan="7" class="muted text-center">Tidak ada transaksi cabang yang menunggu pemeriksaan Operator.</td></tr>
                {% endfor %}
                </tbody></table></div>
                {% if pending.total_pages > 1 %}<div class="qcq-pager"><span>Halaman {{pending.page}} / {{pending.total_pages}}</span><div><a class="btn btn-sm btn-ghost {{'disabled' if pending.page<=1 else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page-1,h_page=verified.page,q=keyword,status=status_filter,per_page=per_page)}}">Sebelumnya</a>{% for n in range(1,pending.total_pages+1) %}{% if n==1 or n==pending.total_pages or (n>=pending.page-2 and n<=pending.page+2) %}<a class="qcq-page {{'active' if n==pending.page else ''}}" href="{{url_for('quick_cashier_queue',p_page=n,h_page=verified.page,q=keyword,status=status_filter,per_page=per_page)}}">{{n}}</a>{% endif %}{% endfor %}<a class="btn btn-sm btn-ghost {{'disabled' if pending.page>=pending.total_pages else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page+1,h_page=verified.page,q=keyword,status=status_filter,per_page=per_page)}}">Berikutnya</a></div></div>{% endif %}
            </div>
        </div>
        <div class="col-12">
            <div class="card">
                <h3>📜 Riwayat Verifikasi</h3>
                <div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Total</th><th>Status</th><th>Verifikator</th><th>Terverifikasi</th></tr></thead>
                <tbody>
                {% for q in verified.rows %}
                <tr>
                    <td>{{ q.invoice_no }}</td>
                    <td>{{ rupiah(q.total) }}</td>
                    <td><span class="badge {{ 'badge-success' if q.status == 'VERIFIED' else 'badge-danger' }}">{{ q.status }}</span></td>
                    <td>{{ q.verifier_name or '-' }}</td>
                    <td>{{ q.verified_at or '-' }}</td>
                </tr>
                {% else %}
                <tr><td colspan="5" class="muted text-center">Belum ada riwayat.</td></tr>
                {% endfor %}
                </tbody></table></div>
                {% if verified.total_pages > 1 %}<div class="qcq-pager"><span>Halaman {{verified.page}} / {{verified.total_pages}}</span><div><a class="btn btn-sm btn-ghost {{'disabled' if verified.page<=1 else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page,h_page=verified.page-1,q=keyword,status=status_filter,per_page=per_page)}}">Sebelumnya</a>{% for n in range(1,verified.total_pages+1) %}{% if n==1 or n==verified.total_pages or (n>=verified.page-2 and n<=verified.page+2) %}<a class="qcq-page {{'active' if n==verified.page else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page,h_page=n,q=keyword,status=status_filter,per_page=per_page)}}">{{n}}</a>{% endif %}{% endfor %}<a class="btn btn-sm btn-ghost {{'disabled' if verified.page>=verified.total_pages else ''}}" href="{{url_for('quick_cashier_queue',p_page=pending.page,h_page=verified.page+1,q=keyword,status=status_filter,per_page=per_page)}}">Berikutnya</a></div></div>{% endif %}
            </div>
        </div>
    </div></div>
    ''', pending=pending, verified=verified, stats=stats, keyword=keyword, status_filter=status_filter, per_page=per_page, queue_user=queue_user, active_op=active_op, rupiah=rupiah)
    return render_page('Verifikasi Quick Cashier', body)

def _qc_locations():
    try:
        rows = q_all('SELECT id, branch_code, name, COALESCE(is_active,1) is_active FROM koperasi_branches WHERE COALESCE(is_active,1)=1 ORDER BY CASE WHEN branch_code="PUSAT" THEN 0 ELSE 1 END, name')
    except Exception:
        rows = q_all('SELECT id, branch_code, name FROM koperasi_branches ORDER BY CASE WHEN branch_code="PUSAT" THEN 0 ELSE 1 END, name')
    return rows or []

def _qc_branch_id_from_value(v):
    try: bid=int(v or 0)
    except Exception: bid=0
    if bid<=0: return None
    return bid if q_one('SELECT id FROM koperasi_branches WHERE id=?',[bid]) else None

def _qc_selected_branch(queue, form_value=None):
    bid=_qc_branch_id_from_value(form_value)
    if bid: return bid
    try:
        if queue and 'stock_branch_id' in queue.keys() and queue['stock_branch_id']:
            return int(queue['stock_branch_id'])
    except Exception: pass
    return None

def _qc_is_pusat_branch(branch_id):
    r=q_one('SELECT branch_code FROM koperasi_branches WHERE id=?',[branch_id]) if branch_id else None
    return bool(r and r['branch_code']=='PUSAT')

def _qc_ensure_location_stock_rows(branch_id):
    if not branch_id: return
    if _qc_is_pusat_branch(branch_id):
        exec_sql('''INSERT OR IGNORE INTO product_branch_stock(product_id, branch_id, stock, min_stock)
                    SELECT id, ?, COALESCE(stock,0), COALESCE(min_stock,0) FROM products WHERE active=1''',[branch_id])
        exec_sql('''UPDATE product_branch_stock
                    SET stock=(SELECT COALESCE(p.stock,0) FROM products p WHERE p.id=product_branch_stock.product_id),
                        min_stock=(SELECT COALESCE(p.min_stock,0) FROM products p WHERE p.id=product_branch_stock.product_id)
                    WHERE branch_id=?''',[branch_id])
    else:
        exec_sql('''INSERT OR IGNORE INTO product_branch_stock(product_id, branch_id, stock, min_stock)
                    SELECT id, ?, 0, COALESCE(min_stock,0) FROM products WHERE active=1''',[branch_id])

def _qc_product_rows(branch_id, q=''):
    if not branch_id: return []
    _qc_ensure_location_stock_rows(branch_id)
    params=[branch_id]
    where='WHERE p.active=1'
    if q:
        qq='%'+str(q).lower().strip()+'%'
        where+=' AND (LOWER(p.product_name) LIKE ? OR LOWER(p.barcode) LIKE ? OR CAST(p.id AS TEXT)=?)'
        params += [qq,qq,str(q).strip()]
    return q_all(f'''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock,COALESCE(pbs.min_stock,p.min_stock,0) min_stock
                     FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                     {where}
                     ORDER BY CASE WHEN COALESCE(pbs.stock,0)>0 THEN 0 ELSE 1 END, p.product_name ASC LIMIT 80''', params)

def _qc_find_product(branch_id, text='', product_id=0):
    if not branch_id: return None
    _qc_ensure_location_stock_rows(branch_id)
    try: product_id=int(product_id or 0)
    except Exception: product_id=0
    if product_id>0:
        return q_one('''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock
                        FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                        WHERE p.id=? AND p.active=1''',[branch_id,product_id])
    text=(text or '').strip(); first=text.split('|')[0].strip()
    if first.isdigit():
        r=q_one('''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock
                   FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                   WHERE p.id=? AND p.active=1''',[branch_id,int(first)])
        if r: return r
    if not text: return None
    return q_one('''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock
                    FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                    WHERE p.active=1 AND (p.barcode=? OR LOWER(p.product_name) LIKE ?)
                    ORDER BY CASE WHEN p.barcode=? THEN 0 ELSE 1 END, p.product_name LIMIT 1''',[branch_id,text,'%'+text.lower()+'%',text])

def _qc_stock_for_conn(conn, product_id, branch_id):
    r=conn.execute('SELECT COALESCE(stock,0) stock FROM product_branch_stock WHERE product_id=? AND branch_id=?',[product_id,branch_id]).fetchone()
    return float(r['stock'] or 0) if r else 0.0

# =========================
# Quick Cashier Verify — Input Barang & Validasi Total
# =========================
