@app.route('/quick-cashier/verify/<int:qid>', methods=['GET', 'POST'])
@login_required
@role_required('admin','branch_admin','kasir','branch_cashier')
def quick_cashier_verify(qid):
    queue=q_one('SELECT * FROM quick_cashier_queue WHERE id=? AND status="PENDING" AND COALESCE(supervisor_review_status,"WAITING") IN ("WAITING","REVISION")',[qid])
    if not queue:
        flash('Antrian tidak ditemukan atau sudah diproses.', 'error')
        return redirect(url_for('quick_cashier_queue'))
    user = current_user()
    cashier_branch_id = get_branch_id()
    locations=_qc_locations()
    # Queue branch is authoritative. Branch staff cannot select another branch.
    queue_branch_id = _qc_selected_branch(queue)
    if user['role'] in ('branch_admin','branch_cashier','kasir') and cashier_branch_id:
        selected_bid = cashier_branch_id
        locations = [b for b in locations if int(b['id']) == int(cashier_branch_id)]
        if queue_branch_id and int(queue_branch_id) != int(cashier_branch_id):
            flash('Antrian ini milik cabang lain dan tidak dapat diproses dari akun ini.', 'error')
            return redirect(url_for('quick_cashier_queue'))
    else:
        selected_bid = queue_branch_id or _qc_selected_branch(queue, request.values.get('stock_branch_id'))
    product_q=(request.values.get('product_q') or '').strip()
    def back(msg='', level='info', bid=None, pq=None):
        if msg: flash(msg, level)
        return redirect(url_for('quick_cashier_verify', qid=qid, stock_branch_id=bid or selected_bid or 0, product_q=pq if pq is not None else product_q, qc_msg=msg, qc_level=level))
    if request.method=='POST':
        action=request.form.get('action','').strip()
        selected_bid=_qc_branch_id_from_value(request.form.get('stock_branch_id')) or selected_bid
        product_q=(request.form.get('product_q') or product_q or '').strip()
        if not action:
            return back('Aksi tidak terbaca. Klik tombol Tambah, Gunakan Lokasi, atau Verifikasi.', 'error', selected_bid, product_q)
        if action=='set_location':
            requested_bid=_qc_branch_id_from_value(request.form.get('stock_branch_id'))
            if user['role'] in ('branch_admin','branch_cashier','kasir') and cashier_branch_id:
                selected_bid=cashier_branch_id
                if requested_bid and int(requested_bid)!=int(cashier_branch_id):
                    return back('Lokasi stok harus sama dengan cabang akun kasir.', 'error', cashier_branch_id, product_q)
            else:
                selected_bid=requested_bid
            if not selected_bid: return back('Pilih lokasi stok terlebih dahulu.', 'error', None, product_q)
            old=_qc_selected_branch(queue)
            if old and old!=selected_bid:
                exec_sql('DELETE FROM quick_cashier_items WHERE queue_id=?',[qid])
            _qc_ensure_location_stock_rows(selected_bid)
            exec_sql('UPDATE quick_cashier_queue SET stock_branch_id=? WHERE id=? AND status="PENDING"',[selected_bid,qid])
            return back(f'Lokasi stok aktif: {get_branch_name(selected_bid)}', 'success', selected_bid, '')
        if not selected_bid:
            return back('Pilih lokasi stok dulu sebelum tambah barang atau verifikasi.', 'error', None, product_q)
        if action=='add_item':
            prod=_qc_find_product(selected_bid, request.form.get('product_query') or product_q, request.form.get('product_id'))
            qty=parse_float(request.form.get('qty',1))
            if not prod: return back('Barang tidak ditemukan. Ketik nama/barcode, tekan Cari, lalu klik Tambah di hasil pencarian.', 'error', selected_bid, product_q)
            if qty<=0: return back('Qty harus lebih dari 0.', 'error', selected_bid, product_q)
            subtotal=qty*float(prod['sell_price'] or 0)
            exec_sql('UPDATE quick_cashier_queue SET stock_branch_id=? WHERE id=? AND status="PENDING"',[selected_bid,qid])
            try:
                exec_sql('''INSERT INTO quick_cashier_items(queue_id, product_id, product_name, qty, price, subtotal, stock_branch_id)
                            VALUES (?, ?, ?, ?, ?, ?, ?)''',[qid,prod['id'],prod['product_name'],qty,prod['sell_price'],subtotal,selected_bid])
            except Exception:
                exec_sql('''INSERT INTO quick_cashier_items(queue_id, product_id, product_name, qty, price, subtotal)
                            VALUES (?, ?, ?, ?, ?, ?)''',[qid,prod['id'],prod['product_name'],qty,prod['sell_price'],subtotal])
            stok=float(prod['stock'] or 0)
            msg=f'{prod["product_name"]} x{qty} masuk tabel verifikasi. Stok lokasi saat ini {stok}.'
            lvl='success' if stok>=qty else 'warning'
            if stok<qty: msg += ' Perhatian: stok tidak cukup, approve akan ditolak sampai stok lokasi ditambah/ditransfer.'
            return back(msg, lvl, selected_bid, product_q)
        if action=='remove_item':
            try: item_id=int(request.form.get('item_id') or 0)
            except Exception: item_id=0
            exec_sql('DELETE FROM quick_cashier_items WHERE id=? AND queue_id=?',[item_id,qid])
            return back('Item dihapus dari tabel verifikasi.', 'warning', selected_bid, product_q)
        if action=='search_product':
            return back('Hasil pencarian diperbarui.', 'info', selected_bid, product_q)
        if action=='final_verify':
            items=q_all('SELECT * FROM quick_cashier_items WHERE queue_id=?',[qid])
            if not items: return back('Belum ada barang yang diperiksa. Tambahkan barang terlebih dahulu.','error',selected_bid,product_q)
            total_items=sum(float(i['subtotal'] or 0) for i in items); diff=round(total_items-float(queue['total'] or 0),2)
            note=(request.form.get('operator_note') or '').strip()[:500]
            op=active_cashier_operator()
            reviewer_id=(op['operator_user_id'] if op else user['id'])
            if user['role'] in ('kasir','branch_cashier') and not op: return back('Sesi Operator aktif diperlukan.','error',selected_bid,product_q)
            exec_sql('''UPDATE quick_cashier_queue SET operator_review_status='CHECKED',operator_verified_by=?,operator_verified_at=?,operator_note=?,supervisor_review_status='WAITING_APPROVAL',stock_branch_id=? WHERE id=? AND status='PENDING' ''',[reviewer_id,now_str(),note or f'Selisih barang vs pembayaran: {diff}',selected_bid,qid])
            log_action('QC_OPERATOR_VERIFIED','quick_cashier_queue',qid,f'Operator review; diff={diff}; branch={selected_bid}')
            flash('Pemeriksaan Operator selesai. Transaksi dikirim ke Supervisor untuk keputusan final.','success')
            return redirect(url_for('quick_cashier_queue'))
        return back(f'Aksi tidak dikenal: {action}', 'error', selected_bid, product_q)
    # Render
    selected_bid = cashier_branch_id if user['role'] in ('branch_admin','branch_cashier','kasir') and cashier_branch_id else (_qc_selected_branch(queue) or _qc_selected_branch(queue, request.args.get('stock_branch_id')))
    product_q=(request.args.get('product_q') or '').strip()
    branch_name=get_branch_name(selected_bid) if selected_bid else 'Belum dipilih'
    products=_qc_product_rows(selected_bid, product_q) if selected_bid else []
    items=q_all('SELECT * FROM quick_cashier_items WHERE queue_id=? ORDER BY id DESC',[qid])
    total_barang=sum(float(i['subtotal'] or 0) for i in items)
    selisih=round(total_barang-float(queue['total'] or 0),2); abs_selisih=abs(selisih)
    qc_msg=request.args.get('qc_msg',''); qc_level=request.args.get('qc_level','info')
    body=render_template_string('''
    <div class="qc-verify-page">
      {% if qc_msg %}<div class="flash flash-{{qc_level}} qc-visible-message">{{qc_msg}}</div>{% endif %}
      <div class="card qc-verify-hero"><div><h2>📦 Verifikasi Barang — {{ queue.invoice_no }}</h2><p>Total bayar: <b>{{ rupiah(queue.total) }}</b> · Lokasi stok: <b>{{ branch_name }}</b> · Item tabel: <b>{{ items|length }}</b></p></div><a href="{{ url_for('quick_cashier_queue') }}" class="btn btn-ghost">← Kembali</a></div>
      <div class="card qc-location-card"><h3>1. Pilih lokasi stok</h3><form method="POST"><input type="hidden" name="action" value="set_location"><select name="stock_branch_id" required><option value="">-- Pilih lokasi stok --</option>{% for b in locations %}<option value="{{b.id}}" {% if selected_bid and b.id==selected_bid %}selected{% endif %}>{{b.name}} ({{b.branch_code}})</option>{% endfor %}</select><button type="submit" class="btn-success">Gunakan Lokasi</button></form></div>
      <div class="qc-kpis"><article><span>Total Barang</span><b>{{ rupiah(total_barang) }}</b></article><article><span>Total Bayar</span><b>{{ rupiah(queue.total) }}</b></article><article class="{{ 'ok' if selisih==0 else 'warn' }}"><span>Selisih</span><b>{% if selisih > 0 %}+ {{ rupiah(abs_selisih) }}{% elif selisih < 0 %}- {{ rupiah(abs_selisih) }}{% else %}Sesuai{% endif %}</b></article></div>
      {% if selected_bid %}<div class="grid"><div class="col-5"><div class="card"><h3>2. Cari & Tambah Barang</h3><form method="GET" class="qc-search-form"><input type="hidden" name="stock_branch_id" value="{{selected_bid}}"><input name="product_q" value="{{product_q}}" placeholder="Cari nama atau scan barcode"><button type="submit" class="btn-ghost">Cari</button></form><form method="POST" class="qc-add-form"><input type="hidden" name="action" value="add_item"><input type="hidden" name="stock_branch_id" value="{{selected_bid}}"><input type="hidden" name="product_q" value="{{product_q}}"><input name="product_query" list="qcProducts" placeholder="Pilih barang dari hasil pencarian" required><datalist id="qcProducts">{% for p in products %}<option value="{{p.id}} | {{p.barcode}} | {{p.product_name}} | stok {{p.stock}}"></option>{% endfor %}</datalist><input type="number" step="0.001" min="0.001" name="qty" value="1" required><button type="submit" class="btn-success">Tambah Barang</button></form><div class="qc-product-results"><h4>Barang Tersedia</h4>{% for p in products %}<form method="POST" class="qc-product-row"><input type="hidden" name="action" value="add_item"><input type="hidden" name="stock_branch_id" value="{{selected_bid}}"><input type="hidden" name="product_id" value="{{p.id}}"><input type="hidden" name="product_q" value="{{product_q}}"><span><b>{{p.product_name}}</b><small>{{p.barcode}} · {{rupiah(p.sell_price)}} · Stok {{p.stock}}</small></span><input type="number" step="0.001" min="0.001" name="qty" value="1"><button type="submit" class="btn-sm btn-success">Tambah</button></form>{% else %}<p class="muted small">Tidak ada hasil. Coba ketik nama/barcode lain.</p>{% endfor %}</div></div></div><div class="col-7"><div class="card"><div class="kartu"><h3>3. Barang yang Diverifikasi</h3><form method="POST"><input type="hidden" name="action" value="final_verify"><input type="hidden" name="stock_branch_id" value="{{selected_bid}}"><input name="operator_note" placeholder="Catatan pemeriksaan Operator" style="margin-bottom:7px"><button type="submit" class="btn-success">Kirim ke Supervisor</button></form></div><div class="table-wrap"><table><thead><tr><th>Barang</th><th>Qty</th><th>Harga</th><th>Subtotal</th><th>Aksi</th></tr></thead><tbody>{% for i in items %}<tr><td>{{i.product_name}}</td><td>{{i.qty}}</td><td>{{rupiah(i.price)}}</td><td>{{rupiah(i.subtotal)}}</td><td><form method="POST"><input type="hidden" name="action" value="remove_item"><input type="hidden" name="stock_branch_id" value="{{selected_bid}}"><input type="hidden" name="item_id" value="{{i.id}}"><button type="submit" class="btn-sm btn-danger">Hapus</button></form></td></tr>{% else %}<tr><td colspan="5" class="muted text-center">Belum ada barang masuk tabel verifikasi.</td></tr>{% endfor %}</tbody></table></div></div></div></div>{% else %}<div class="card qc-location-empty"><h3>Lokasi belum dipilih</h3><p>Pilih lokasi stok dulu agar cari dan tambah barang aktif.</p></div>{% endif %}
    </div>
    ''', queue=queue, locations=locations, selected_bid=selected_bid, branch_name=branch_name, products=products, items=items, total_barang=total_barang, selisih=selisih, abs_selisih=abs_selisih, product_q=product_q, qc_msg=qc_msg, qc_level=qc_level, rupiah=rupiah)
    return render_page('Verifikasi Barang', body)

@app.route('/cashier', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'kasir', 'branch_admin', 'branch_cashier')
def cashier():
    user=current_user()
    blocked=require_branch_for_branch_role(user)
    if blocked: return blocked
    bid,_branch_warning=resolve_operational_branch(user)
    cart_branch = session.get('cart_branch_id', '__unset__')
    branch_key = str(bid) if bid else 'PUSAT'
    if cart_branch != branch_key:
        save_cart([]); session['cart_branch_id'] = branch_key
    cart = get_cart()
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'add_item':
            barcode = request.form.get('barcode', '').strip()
            qty = parse_float(request.form.get('qty', 1) or 1)
            bid,_branch_warning=resolve_operational_branch(user)
            if bid:
                prod = q_one('''SELECT p.id,p.barcode,p.product_name,p.sell_price,COALESCE(pbs.stock,0) stock
                                FROM products p LEFT JOIN product_branch_stock pbs ON pbs.product_id=p.id AND pbs.branch_id=?
                                WHERE p.barcode=? AND p.active=1''',[bid,barcode])
            else:
                prod = q_one('SELECT id,barcode,product_name,sell_price,COALESCE(stock,0) stock FROM products WHERE barcode=? AND active=1',[barcode])
            if not barcode:
                flash('Barcode wajib diisi / discan.', 'warning')
            elif not prod:
                flash('Barang tidak ditemukan.', 'error')
            elif float(prod['stock']) < qty:
                flash('Stok tidak mencukupi.', 'error')
            else:
                found = False
                for item in cart:
                    if item['product_id'] == int(prod['id']):
                        item['qty'] += qty; item['subtotal'] = item['qty'] * item['price']
                        found = True; break
                if not found:
                    cart.append({'product_id': int(prod['id']), 'barcode': prod['barcode'], 'product_name': prod['product_name'], 'qty': qty, 'price': float(prod['sell_price']), 'subtotal': qty * float(prod['sell_price'])})
                save_cart(cart)
                flash(f"{prod['product_name']} masuk keranjang.", 'success')
            return redirect(url_for('cashier'))
        elif action == 'clear':
            save_cart([]); flash('Keranjang dikosongkan.', 'warning')
            return redirect(url_for('cashier'))
        elif action == 'save_sale':
            if not cart:
                flash('Keranjang kosong.', 'error')
                return redirect(url_for('cashier'))
            total = sum(float(i['subtotal']) for i in cart)
            member_id = request.form.get('member_id') or None
            customer_name = request.form.get('customer_name', '').strip()
            paid = parse_float(request.form.get('paid', 0) or 0)
            note = request.form.get('note', '').strip()
            payment_method = request.form.get('payment_method', 'tunai')
            invoice = gen_code('INV')
            change_amount = 0
            if payment_method == 'tunai':
                if paid < total:
                    flash('Nominal bayar kurang dari total.', 'error')
                    return redirect(url_for('cashier'))
                change_amount = paid - total
            elif payment_method == 'wallet':
                if not member_id:
                    flash('Bayar wallet wajib pilih member.', 'error')
                    return redirect(url_for('cashier'))
                member_saldo = q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id=?', [member_id])['saldo']
                if member_saldo < total:
                    flash(f'Saldo wallet member tidak cukup. Saldo {rupiah(member_saldo)}', 'error')
                    return redirect(url_for('cashier'))
                saldo_sebelum = member_saldo
                saldo_setelah = saldo_sebelum - total
                exec_sql('INSERT INTO saldo_history(member_id, tipe, nominal, saldo_sebelum, saldo_setelah, keterangan, reference_id, created_by) VALUES (?, "KELUAR", ?, ?, ?, "Pembayaran via wallet kasir", ?, ?)', [member_id, total, saldo_sebelum, saldo_setelah, 0, session.get('user_id')])
                paid = total
            else:
                paid = total
            # Revalidate every cart line against the current branch immediately before posting.
            bid,_branch_warning=resolve_operational_branch(user)
            for item in cart:
                available = get_product_stock(item['product_id'], bid)
                if available < float(item['qty']):
                    flash(f"Stok {item['product_name']} di {get_branch_name(bid)} tidak cukup. Tersedia {available}.", 'error')
                    return redirect(url_for('cashier'))
            sid = exec_sql('INSERT INTO sales(invoice_no,trx_date,member_id,cashier_id,customer_name,total,paid,change_amount,note,status,payment_method,branch_id) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, "Posted", ?, ?)', [invoice,today_str(),member_id,cashier_operator_id(),customer_name,total,paid,change_amount,note,payment_method,bid])
            exec_sql('UPDATE sales SET cashier_session_id=? WHERE id=?',[cashier_operator_session_id(),sid])
            payload = []
            for item in cart:
                unit_cost = consume_from_batches(item['product_id'], item['qty'], bid)
                payload.append((sid, item['product_id'], item['barcode'], item['product_name'], item['qty'], item['price'], item['subtotal'], unit_cost))
                update_branch_stock(item['product_id'], item['qty'], bid, 'subtract')
                log_stock_history(item['product_id'], item['qty'], 'Penjualan', reference_type='sales', reference_id=sid, note=f'Invoice {invoice}')
            exec_sql('INSERT INTO sales_items(sales_id, product_id, barcode, product_name, qty, price, subtotal, unit_cost) VALUES (?, ?, ?, ?, ?, ?, ?, ?)', payload, many=True)
            log_action('CREATE', 'sales', sid, f'Transaksi {invoice} total {total} metode {payment_method}')
            save_cart([])
            flash(f'Transaksi tersimpan. Invoice {invoice}. Kembalian {rupiah(change_amount)}', 'success')
            return redirect(url_for('cashier'))
    members_rows = q_all("SELECT id, member_code, name FROM members WHERE status='Aktif' ORDER BY name ASC")
    cashier_branch_name=get_branch_name(bid)
    total = sum(float(i['subtotal']) for i in cart)
    body = render_template_string('''
    <div class="sales-suite cashier-suite">
      <header class="sales-hero"><div><span>POINT OF SALE</span><h2>Kasir</h2><p>Lokasi aktif: <b>{{cashier_branch_name}}</b>. Pemindaian dan pengurangan stok hanya memakai persediaan lokasi ini.</p></div><div class="sales-hero-chip"><small>Total keranjang</small><b>{{rupiah(total)}}</b></div></header>
      <div class="grid sales-main-grid">
        <div class="col-4"><div class="card"><h2>🧾 Kasir</h2>
            <div class="muted small">Scan barcode untuk menambah item</div>
            <hr>
            <form method="post"><input type="hidden" name="action" value="add_item">
                <div class="form-group"><label>Barcode</label><input name="barcode" placeholder="Scan barcode..." autofocus></div>
                <div class="form-group"><label>Qty</label><input type="number" name="qty" value="1"></div>
                <button type="submit">Tambah Produk Kredit</button>
            </form>
            <hr>
            <h3>Total: <strong>{{ rupiah(total) }}</strong></h3>
            <form method="post" id="saleForm"><input type="hidden" name="action" value="save_sale">
                <div class="form-group"><label>Member</label><select name="member_id" id="member_id" onchange="toggleMemberInfo()"><option value="">Umum</option>{% for m in members_rows %}<option value="{{ m['id'] }}">{{ m['member_code'] }} — {{ m['name'] }}</option>{% endfor %}</select></div>
                <div class="form-group"><label>Nama Pelanggan</label><input name="customer_name" placeholder="(opsional)"></div>
                <div class="form-group"><label>Pilih Metode Pembayaran</label>
                    <select name="payment_method" id="payment_method" onchange="togglePaid()">
                        <option value="tunai">💰 Tunai</option>
                        <option value="wallet">💳 Wallet (Saldo Member)</option>
                    </select>
                </div>
                <div class="form-group" id="paid_row"><label>Bayar</label><input type="number" name="paid" id="paid_input" value="{{ total }}"></div>
                <div class="form-group"><label>Catatan</label><textarea name="note" style="min-height:50px;"></textarea></div>
                <button type="submit" class="btn-success">💾 Simpan Transaksi</button>
            </form>
            <form method="post" style="margin-top:8px;"><input type="hidden" name="action" value="clear"><button class="btn-ghost btn-danger" type="submit">🗑️ Kosongkan</button></form>
        </div></div>
        <div class="col-8"><div class="card"><h2>Keranjang</h2>
            <div class="table-wrap"><table><thead><tr><th>Barang</th><th>Qty</th><th>Harga</th><th>Subtotal</th></tr></thead>
            <tbody>{% for i in cart %}<tr><td>{{ i['product_name'] }}</td><td>{{ i['qty'] }}</td><td>{{ rupiah(i['price']) }}</td><td>{{ rupiah(i['subtotal']) }}</td></tr>{% else %}<tr><td colspan="4" class="muted text-center">Keranjang kosong.</td></tr>{% endfor %}</tbody></table></div>
        </div></div>
      </div>
    </div>
    <script>
    function togglePaid(){
        var pm = document.getElementById('payment_method').value;
        var row = document.getElementById('paid_row');
        var inp = document.getElementById('paid_input');
        var total = {{ total }};
        if(pm==='wallet'){row.style.display='none';inp.value=total;}
        else{row.style.display='block';}
    }
    function toggleMemberInfo(){
        var mid = document.getElementById('member_id').value;
        var pm = document.getElementById('payment_method');
        if(!mid){pm.value='tunai';togglePaid();}
    }
    </script>
    ''', cart=cart, total=total, members_rows=members_rows, rupiah=rupiah, cashier_branch_name=cashier_branch_name)
    return render_page('Kasir', cashier_operator_banner()+body)

