@app.route('/loans', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'bendahara', 'user', 'branch_admin')
def loans():
    user = current_user()
    is_staff = user['role'] in ('admin', 'bendahara', 'branch_admin')
    my_member = q_one('SELECT * FROM members WHERE member_code=?', [f'EMP-{user["employee_number"]}']) if user['role'] == 'user' else None

    if request.method == 'POST':
        if not is_staff:
            flash('Pengajuan anggota hanya dapat dibuat dari menu Ajukan Pinjaman.', 'warning')
            return redirect(url_for('apply_loan'))
        action = request.form.get('action', '')
        loan_id = int(request.form.get('loan_id') or 0)
        loan = q_one('SELECT * FROM loans WHERE id=?', [loan_id]) if loan_id else None
        if not loan:
            flash('Data pinjaman tidak ditemukan.', 'error')
            return redirect(url_for('loans'))
        if action == 'approve_loan':
            schedules = q_one('SELECT COUNT(*) AS n FROM loan_schedules WHERE loan_id=?', [loan_id])['n'] or 0
            if loan['status'] != 'CALCULATED' or schedules < 1:
                flash('Pinjaman hanya dapat disetujui setelah kalkulasi final dan jadwal angsuran tersedia.', 'error')
                return redirect(url_for('loan_detail', loan_id=loan_id))
            exec_sql('UPDATE loans SET status="Berjalan", current_stage="ACTIVE", progress_percent=80, approved_by=?, approved_at=? WHERE id=?', [user['id'], now_str(), loan_id])
            exec_sql("UPDATE approval_requests SET status='Approved', approved_by=?, approved_at=? WHERE ref_table='loans' AND ref_id=? AND status='Pending'", [user['id'], now_str(), loan_id])
            add_timeline(loan_id, 'APPROVED', 'Pengajuan disetujui; pinjaman resmi berjalan.', user['id'])
            log_action('LOAN_APPROVED', 'loans', loan_id, loan['loan_no'])
            notify_member(loan['member_id'], 'Pinjaman Disetujui', f'Pengajuan {loan["loan_no"]} telah disetujui dan mulai berjalan.')
            flash('Pinjaman berhasil disetujui dan diaktifkan.', 'success')
        elif action == 'reject_loan':
            reason = request.form.get('reject_reason', '').strip()
            if loan['status'] not in ('SUBMITTED', 'CALCULATED'):
                flash('Status pinjaman ini tidak dapat ditolak.', 'error')
            elif len(reason) < 10:
                flash('Alasan penolakan wajib jelas, minimal 10 karakter.', 'error')
            else:
                exec_sql('UPDATE loans SET status="Ditolak", current_stage="REJECTED", progress_percent=100, admin_note=? WHERE id=?', [reason, loan_id])
                exec_sql("UPDATE approval_requests SET status='Rejected', reason=?, approved_by=?, approved_at=? WHERE ref_table='loans' AND ref_id=? AND status='Pending'", [reason, user['id'], now_str(), loan_id])
                add_timeline(loan_id, 'REJECTED', reason, user['id'])
                log_action('LOAN_REJECTED', 'loans', loan_id, reason)
                notify_member(loan['member_id'], 'Pengajuan Pinjaman Ditolak', f'{loan["loan_no"]}: {reason}')
                flash('Pengajuan ditolak dan alasan telah dikirim kepada anggota.', 'warning')
        return redirect(url_for('loans'))

    if is_staff:
        loans_rows = q_all('''SELECT l.*,m.member_code,m.name,lt.name loan_type_name,
            COALESCE((SELECT SUM(amount) FROM loan_payments p WHERE p.loan_id=l.id AND p.status="VERIFIED"),0) paid
            FROM loans l LEFT JOIN members m ON m.id=l.member_id LEFT JOIN loan_types lt ON lt.id=l.loan_type_id
            ORDER BY CASE l.status WHEN "SUBMITTED" THEN 0 WHEN "CALCULATED" THEN 1 WHEN "Berjalan" THEN 2 WHEN "Ditolak" THEN 3 ELSE 4 END,l.id DESC''')
    else:
        loans_rows = q_all('''SELECT l.*,m.member_code,m.name,lt.name loan_type_name,
            COALESCE((SELECT SUM(amount) FROM loan_payments p WHERE p.loan_id=l.id AND p.status="VERIFIED"),0) paid
            FROM loans l LEFT JOIN members m ON m.id=l.member_id LEFT JOIN loan_types lt ON lt.id=l.loan_type_id
            WHERE l.member_id=? ORDER BY l.id DESC''', [my_member['id']]) if my_member else []
    data=[]
    for r in loans_rows:
        d=dict(r); d['remaining']=max(0,float(d.get('total_receivable') or 0)-float(d.get('paid') or 0)); d['meta']=loan_status_meta(d.get('status')); data.append(d)
    counts={k:sum(1 for x in data if x['status']==k) for k in ('SUBMITTED','CALCULATED','Berjalan','Lunas','Ditolak')}
    total_outstanding=sum(x['remaining'] for x in data if x['status']=='Berjalan')

    body=render_template_string('''
    <div class="loan-hero"><div><span class="loan-eyebrow">PUSAT KREDIT KOPERASI</span><h2>{{ 'Meja Analisis Kredit' if is_staff else 'Pinjaman Saya' }}</h2><p>{{ 'Periksa kelengkapan, kalkulasi, putuskan, lalu pantau pembayaran dalam alur yang tertib.' if is_staff else 'Pantau pengajuan, keputusan, kontrak, jadwal, dan pembayaran dari satu halaman.' }}</p></div><div class="loan-hero-actions">{% if not is_staff %}<a class="btn btn-success" href="{{url_for('apply_loan')}}">＋ Ajukan Kredit</a>{% endif %}</div></div>
    <div class="loan-steps"><div class="done"><b>1</b><span>Pengajuan</span></div><div><b>2</b><span>Pemeriksaan</span></div><div><b>3</b><span>Kalkulasi</span></div><div><b>4</b><span>Keputusan</span></div><div><b>5</b><span>Angsuran</span></div></div>
    <div class="metrics"><div class="metric"><div class="label">Menunggu Pemeriksaan</div><div class="value">{{counts.SUBMITTED}}</div></div><div class="metric"><div class="label">Menunggu Keputusan</div><div class="value">{{counts.CALCULATED}}</div></div><div class="metric"><div class="label">Pinjaman Aktif</div><div class="value">{{counts.Berjalan}}</div></div><div class="metric"><div class="label">Sisa Berjalan</div><div class="value">{{rupiah(total_outstanding)}}</div></div></div>
    <div class="card"><div class="kartu"><div><h2>{{ 'Antrean & Portofolio Kredit' if is_staff else 'Riwayat Pengajuan Kredit' }}</h2><div class="muted small">Klik Detail untuk melihat prosedur, timeline, dan jadwal secara lengkap.</div></div>{% if is_staff %}<a class="btn btn-sm btn-ghost" href="{{url_for('loan_admin_check')}}">Pemeriksaan Sistem</a>{% endif %}</div>
    <div class="loan-list">{% for r in rows %}<article class="loan-item"><div class="loan-item-main"><div class="loan-number">{{r.loan_no}}</div><h3>{{r.name if is_staff else (r.loan_type_name or 'Pinjaman Koperasi')}}</h3><div class="muted small">{{r.member_code}} · {{r.loan_type_name or 'Jenis belum ditentukan'}} · {{r.loan_date}}</div></div><div class="loan-amount"><small>Pokok</small><strong>{{rupiah(r.principal)}}</strong><span>Sisa {{rupiah(r.remaining)}}</span></div><div class="loan-state"><span class="badge {{r.meta[1]}}">{{r.meta[0]}}</span><div class="progress-bar"><div class="progress-fill" style="width:{{r.meta[2]}}%"></div></div></div><div class="loan-actions"><a href="{{url_for('loan_detail',loan_id=r.id)}}" class="btn btn-sm btn-ghost">Detail</a>{% if is_staff and r.status=='SUBMITTED' %}<a href="{{url_for('calculate_loan',loan_id=r.id)}}" class="btn btn-sm btn-warn">Analisis</a>{% endif %}{% if is_staff and r.status=='CALCULATED' %}<form method="post" style="display:inline"><input type="hidden" name="action" value="approve_loan"><input type="hidden" name="loan_id" value="{{r.id}}"><button class="btn btn-sm btn-success" data-confirm="Setujui hasil kalkulasi dan aktifkan pinjaman?">Setujui</button></form>{% endif %}{% if is_staff and r.status in ('SUBMITTED','CALCULATED') %}<details class="loan-reject"><summary>Tolak</summary><form method="post"><input type="hidden" name="action" value="reject_loan"><input type="hidden" name="loan_id" value="{{r.id}}"><input name="reject_reason" minlength="10" placeholder="Alasan penolakan" required><button class="btn btn-sm btn-danger">Konfirmasi</button></form></details>{% endif %}{% if not is_staff and r.status=='Berjalan' %}<a href="{{url_for('pay_loan_installment',loan_id=r.id)}}" class="btn btn-sm btn-success">Bayar</a>{% endif %}</div></article>{% else %}<div class="loan-empty"><div>◇</div><h3>Belum ada pengajuan</h3><p>Mulai dari simulasi agar nominal dan tenor sesuai kemampuan.</p>{% if not is_staff %}<a class="btn" href="{{url_for('apply_loan')}}">Ajukan Kredit</a>{% endif %}</div>{% endfor %}</div></div>
    ''', rows=data, counts=counts, total_outstanding=total_outstanding, is_staff=is_staff, rupiah=rupiah)
    return render_page('Kredit & Pinjaman', body)

@app.route('/loans/admin-check')
@login_required
@role_required('admin', 'bendahara', 'supervisor')
def loan_admin_check():
    db_path = str(Path(DB_NAME).resolve())
    rows = q_all("SELECT l.id,l.loan_no,l.status,l.loan_date,l.principal,m.name,m.member_code FROM loans l LEFT JOIN members m ON m.id=l.member_id ORDER BY l.id DESC LIMIT 100")
    pending = q_one("SELECT COUNT(*) n FROM loans WHERE status='SUBMITTED'")['n'] or 0
    approvals = q_one("SELECT COUNT(*) n FROM approval_requests WHERE ref_table='loans' AND status='Pending'")['n'] or 0
    body = render_template_string("""
    <div class='card'><h2>Pemeriksaan Sistem Pengajuan</h2>
      <div class='metrics'><div class='metric'><div class='label'>Build</div><div class='value'>CREDIT-FIX-2026-07-17</div></div><div class='metric'><div class='label'>SUBMITTED</div><div class='value'>{{pending}}</div></div><div class='metric'><div class='label'>Approval Pending</div><div class='value'>{{approvals}}</div></div></div>
      <div class='flash flash-info'><b>Database aktif:</b> {{db_path}}</div>
      <div class='table-wrap'><table><thead><tr><th>ID</th><th>Nomor</th><th>Anggota</th><th>Tanggal</th><th>Nominal</th><th>Status</th></tr></thead><tbody>{% for x in rows %}<tr><td>{{x.id}}</td><td>{{x.loan_no}}</td><td>{{x.member_code}} - {{x.name}}</td><td>{{x.loan_date}}</td><td>{{rupiah(x.principal)}}</td><td>{{x.status}}</td></tr>{% else %}<tr><td colspan='6'>Database aktif belum memiliki data pengajuan.</td></tr>{% endfor %}</tbody></table></div>
    </div>
    """, rows=rows, pending=pending, approvals=approvals, db_path=db_path, rupiah=rupiah)
    return render_page('Pemeriksaan Pengajuan', body)

# =========================
# Pegawai
# =========================
@app.route('/pegawai', methods=['GET'])
@login_required
@role_required('admin')
def pegawai():
    key = request.args.get('q', '').strip()
    role_filter = request.args.get('role', '').strip()
    params = []
    sql = 'SELECT id, username, full_name, role, active, status, created_at FROM users WHERE 1=1'
    if key:
        sql += ' AND (full_name LIKE ? OR username LIKE ?)'
        params.extend([f'%{key}%', f'%{key}%'])
    if role_filter:
        sql += ' AND role = ?'
        params.append(role_filter)
    sql += ' ORDER BY id DESC'
    rows = q_all(sql, params)
    total = q_one('SELECT COUNT(*) as n FROM users')['n'] or 0
    active_count = q_one('SELECT COUNT(*) as n FROM users WHERE active=1')['n'] or 0
    roles = q_all('SELECT role, COUNT(*) as cnt FROM users GROUP BY role ORDER BY cnt DESC')
    body = render_template_string('''
    <div class="card">
        <div class="kartu">
            <div><h2>👥 Daftar Pegawai</h2><div class="muted small">Total {{ total }} pegawai ({{ active_count }} aktif)</div></div>
            <div class="top-actions">
                <a href="{{ url_for('export_pegawai') }}" class="btn btn-sm btn-success">📥 Export Excel</a>
            </div>
        </div>
    </div>
    <div class="metrics">
        {% for r in roles %}
        <div class="metric"><div class="label">👤 {{ r.role|capitalize }}</div><div class="value" style="color:#2563eb;">{{ r.cnt }}</div></div>
        {% endfor %}
        <div class="metric"><div class="label">📊 Total</div><div class="value" style="color:#10b981;">{{ total }}</div></div>
    </div>
    <div class="card">
        <div class="kartu">
            <form method="get" style="display:flex;gap:8px;flex-wrap:wrap;align-items:end;width:auto;">
                <div><label class="small muted">Cari</label><input name="q" value="{{ key }}" placeholder="Nama / Username" style="width:180px;"></div>
                <div><label class="small muted">Role</label><select name="role" style="width:130px;" onchange="this.form.submit()"><option value="">Semua Role</option>{% for r in roles %}<option value="{{ r.role }}" {% if r.role == role_filter %}selected{% endif %}>{{ r.role|capitalize }}</option>{% endfor %}</select></div>
                <button class="btn-ghost" type="submit">🔍 Filter</button>
                {% if key or role_filter %}<a href="{{ url_for('pegawai') }}" class="btn btn-sm btn-ghost">✕ Reset</a>{% endif %}
            </form>
        </div>
        <div class="table-wrap">
            <table>
                <thead><tr><th>Username</th><th>Nama</th><th>Role</th><th>Status</th><th>Tgl Daftar</th></tr></thead>
                <tbody>
                {% for r in rows %}
                <tr>
                    <td><strong>{{ r.username }}</strong></td>
                    <td>{{ r.full_name }}</td>
                    <td><span class="badge badge-info">{{ r.role }}</span></td>
                    <td><span class="badge {% if r.active %}badge-success{% else %}badge-danger{% endif %}">{% if r.active %}✅ Aktif{% else %}❌ Nonaktif{% endif %}</span></td>
                    <td class="muted small">{{ r.created_at[:10] }}</td>
                </tr>
                {% else %}
                <tr><td colspan="5" class="muted text-center">Belum ada pegawai.</td></tr>
                {% endfor %}
                </tbody>
            </table>
        </div>
    </div>
    ''', rows=rows, total=total, active_count=active_count, roles=roles, key=key, role_filter=role_filter)
    return render_page('Daftar Pegawai', body)

@app.route('/pegawai/export-excel')
@login_required
@role_required('admin')
def export_pegawai():
    rows = q_all('SELECT username, full_name, phone, role, CASE WHEN active=1 THEN "Aktif" ELSE "Nonaktif" END as status, status as approval, created_at FROM users ORDER BY id DESC')
    return to_excel({'pegawai': [dict(r) for r in rows]}, 'daftar_pegawai.xlsx')

@app.route('/users', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def users():
    role_catalog={
      'admin':{'label':'Administrator Pusat','short':'ADMIN','group':'Pusat','desc':'Kontrol penuh sistem, pengguna, keuangan, operasional, dan audit.','color':'#173d34'},
      'manager':{'label':'Manager Monitoring','short':'MGR','group':'Pusat','desc':'Monitoring kinerja, keuangan, operator, dan seluruh cabang.','color':'#315a88'},
      'bendahara':{'label':'Bendahara','short':'FIN','group':'Pusat','desc':'Keuangan, wallet, simpanan, kredit, dan laporan.','color':'#8a5d16'},
      'supervisor':{'label':'Supervisor','short':'SPV','group':'Operasional','desc':'Jadwal operator, verifikasi transaksi, dan approval inventori.','color':'#63317c'},
      'leader':{'label':'Leader Inventori','short':'LDR','group':'Operasional','desc':'Inventori akhir bulan untuk seluruh cabang dan PUSAT.','color':'#176f58'},
      'warehouse_center':{'label':'Gudang Pusat','short':'WH','group':'Operasional','desc':'Kontrol stok pusat, distribusi cabang, PO, dan supplier.','color':'#0e6572'},
      'kasir':{'label':'Kasir Pusat','short':'KSR','group':'Transaksi','desc':'Transaksi kasir dan operasional penjualan pusat.','color':'#a34b20'},
      'branch_admin':{'label':'Admin Cabang','short':'BA','group':'Cabang','desc':'Administrasi, stok, transaksi, dan laporan cabang tertentu.','color':'#45556c'},
      'branch_cashier':{'label':'Kasir Cabang','short':'BC','group':'Cabang','desc':'Terminal kasir cabang dan Secure Operator Session.','color':'#19725d'},
      'supplier':{'label':'Supplier','short':'SUP','group':'Eksternal','desc':'Portal konfirmasi Purchase Order dan pengiriman barang.','color':'#73502d'},
      'user':{'label':'Anggota / Pegawai','short':'USR','group':'Eksternal','desc':'Wallet, simpanan, pinjaman, transaksi, dan SHU pribadi.','color':'#526275'},
    }
    branch_roles={'branch_admin','branch_cashier'}
    if request.method=='POST':
        action=request.form.get('action','create')
        if action=='toggle_status':
            user_id=request.form.get('user_id',type=int);current=q_one('SELECT active,full_name,username FROM users WHERE id=?',[user_id])
            if not current: flash('Pengguna tidak ditemukan.','error')
            elif user_id==session.get('user_id'): flash('Akun yang sedang digunakan tidak dapat dinonaktifkan sendiri.','error')
            else:
                new_active=0 if current['active'] else 1;exec_sql('UPDATE users SET active=?,status=? WHERE id=?',[new_active,'ACTIVE' if new_active else 'NONACTIVE',user_id]);log_action('UPDATE','users',user_id,f'Status {current["username"]} -> {new_active}');flash(f'Akun {current["full_name"] or current["username"]} sekarang {"aktif" if new_active else "nonaktif"}.','success')
            return redirect(url_for('users',q=request.args.get('q',''),role=request.args.get('role','')))
        if action=='create':
            username=(request.form.get('username') or '').strip();full_name=(request.form.get('full_name') or '').strip();password=request.form.get('password') or '';role=(request.form.get('role') or '').strip();branch_id=request.form.get('branch_id') or None;activate=request.form.get('activate_now')=='1'
            if role not in role_catalog: flash('Role tidak valid.','error')
            elif not username or not full_name or len(password)<8: flash('Username, nama, dan password minimal 8 karakter wajib diisi.','error')
            elif role in branch_roles and not branch_id: flash('Role cabang wajib memiliki cabang penempatan.','error')
            else:
                if role not in branch_roles: branch_id=None
                try:
                    uid=exec_sql('INSERT INTO users(username,full_name,password_hash,role,active,status,branch_id) VALUES(?,?,?,?,?,?,?)',[username,full_name,hash_password(password),role,1 if activate else 0,'ACTIVE' if activate else 'NONACTIVE',branch_id]);log_action('CREATE','users',uid,f'{username}; role={role}');flash(f'Akun {full_name} berhasil dibuat sebagai {role_catalog[role]["label"]}.','success');return redirect(url_for('users',created=uid))
                except sqlite3.IntegrityError: flash('Username sudah digunakan.','error')
    q=(request.args.get('q') or '').strip();role_filter=(request.args.get('role') or '').strip();status_filter=(request.args.get('status') or '').strip();params=[];where=['1=1']
    if q: where.append('(u.username LIKE ? OR u.full_name LIKE ? OR COALESCE(b.name,\'\') LIKE ?)');params += [f'%{q}%']*3
    if role_filter in role_catalog: where.append('u.role=?');params.append(role_filter)
    if status_filter in ('active','inactive'): where.append('u.active=?');params.append(1 if status_filter=='active' else 0)
    rows=q_all('SELECT u.*,b.name branch_name,b.branch_code FROM users u LEFT JOIN koperasi_branches b ON b.id=u.branch_id WHERE '+' AND '.join(where)+' ORDER BY u.id DESC',params)
    branches=q_all('SELECT id,branch_code,name FROM koperasi_branches WHERE is_active=1 ORDER BY name');all_rows=q_all('SELECT role,active,COUNT(*) n FROM users GROUP BY role,active');role_counts={k:{'total':0,'active':0} for k in role_catalog}
    for x in all_rows:
        role_counts.setdefault(x['role'],{'total':0,'active':0});role_counts[x['role']]['total']+=int(x['n']);role_counts[x['role']]['active']+=int(x['n']) if x['active'] else 0
    total=sum(x['total'] for x in role_counts.values());active_total=sum(x['active'] for x in role_counts.values());created=request.args.get('created',type=int)
    body=render_template_string(USERS_ROLE_CENTER_HTML,rows=rows,branches=branches,roles=role_catalog,role_counts=role_counts,total=total,active_total=active_total,q=q,role_filter=role_filter,status_filter=status_filter,branch_roles=branch_roles,created=created)
    return render_page('Pengguna & Role',body)

USERS_ROLE_CENTER_HTML=r'''<style>.ur{display:grid;gap:14px}.ur-hero{display:flex;justify-content:space-between;align-items:end;gap:20px;padding:27px;border-radius:24px;background:radial-gradient(circle at 88% 10%,rgba(106,225,179,.2),transparent 28%),linear-gradient(135deg,#071b28,#164c41);color:#fff}.ur-hero span{color:#dbef7b;font-size:8px;font-weight:950;letter-spacing:.16em}.ur-hero h2{margin:6px 0;color:#fff;font-size:28px}.ur-hero p{margin:0;color:#bed4cc;font-size:10px}.ur-kpis{display:flex;gap:8px}.ur-kpis div{min-width:105px;padding:11px;border:1px solid rgba(255,255,255,.13);border-radius:13px;background:rgba(255,255,255,.08)}.ur-kpis small,.ur-kpis b{display:block}.ur-kpis small{font-size:7px}.ur-kpis b{margin-top:4px;font-size:18px}.ur-roles{display:grid;grid-template-columns:repeat(6,1fr);gap:8px}.ur-role{position:relative;overflow:hidden;padding:12px;border:1px solid #dce6e2;border-radius:15px;background:#fff;color:inherit;text-decoration:none}.ur-role:before{content:'';position:absolute;right:-25px;top:-30px;width:75px;height:75px;border-radius:50%;background:color-mix(in srgb,var(--rc) 10%,white)}.ur-role i{position:relative;display:grid;place-items:center;width:35px;height:35px;border-radius:11px;background:var(--rc);color:#fff;font-style:normal;font-size:8px;font-weight:950}.ur-role b,.ur-role small{position:relative;display:block}.ur-role b{margin-top:8px;font-size:9px}.ur-role small{margin-top:2px;color:#77857f;font-size:7px}.ur-role.active{border-color:var(--rc);box-shadow:0 0 0 3px color-mix(in srgb,var(--rc) 11%,transparent)}.ur-layout{display:grid;grid-template-columns:340px minmax(0,1fr);gap:13px}.ur-form,.ur-list{padding:17px;border:1px solid #dce6e2;border-radius:19px;background:#fff}.ur-form h3,.ur-list h3{margin-top:0}.ur-form form{display:grid;gap:10px}.ur-role-help{padding:10px;border-radius:11px;background:#f1f7f4;color:#52645c;font-size:8px;line-height:1.55}.ur-toggle{display:flex;align-items:center;gap:8px;padding:10px;border-radius:11px;background:#f7faf8}.ur-tools{display:grid;grid-template-columns:1fr 175px 145px auto;gap:7px;margin-bottom:12px}.ur-users{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.ur-user{padding:13px;border:1px solid #e0e8e4;border-radius:15px;background:linear-gradient(145deg,#fff,#f7faf8)}.ur-user.new{border-color:#2d9b75;animation:urPulse 1.2s ease}.ur-user header{display:grid;grid-template-columns:42px 1fr auto;gap:9px;align-items:center}.ur-avatar{display:grid;place-items:center;width:42px;height:42px;border-radius:13px;background:var(--uc);color:#fff;font-weight:950}.ur-user b,.ur-user small{display:block}.ur-user small{color:#77847e;font-size:7px}.ur-status{width:9px;height:9px;border-radius:50%;background:#b9c2be}.ur-status.on{background:#20a675;box-shadow:0 0 0 4px rgba(32,166,117,.12)}.ur-meta{display:flex;gap:5px;flex-wrap:wrap;margin:10px 0}.ur-meta span{padding:5px 7px;border-radius:99px;background:#edf4f1;font-size:7px}.ur-user footer{display:flex;justify-content:space-between;align-items:center;gap:7px}.ur-user footer form{margin:0}.ur-empty{grid-column:1/-1;padding:35px;text-align:center}@keyframes urPulse{50%{box-shadow:0 0 0 7px rgba(45,155,117,.12)}}@media(max-width:1150px){.ur-roles{grid-template-columns:repeat(4,1fr)}.ur-users{grid-template-columns:1fr}}@media(max-width:760px){.ur{padding:0 9px}.ur-hero{margin:0 -9px;padding:22px 17px;border-radius:0 0 24px 24px;align-items:flex-start;flex-direction:column}.ur-hero h2{font-size:23px}.ur-kpis{width:100%;overflow-x:auto}.ur-kpis div{flex:0 0 115px}.ur-roles{display:flex;overflow-x:auto}.ur-role{flex:0 0 145px}.ur-layout{grid-template-columns:1fr}.ur-form,.ur-list{padding:13px}.ur-tools{grid-template-columns:1fr 1fr}.ur-tools input{grid-column:1/-1}.ur-tools button{grid-column:1/-1;min-height:44px}.ur-users{grid-template-columns:1fr}}</style><div class="ur"><header class="ur-hero"><div><span>IDENTITY & ACCESS CONTROL</span><h2>Pengguna & Role</h2><p>Kelola akun berdasarkan fungsi bisnis, penempatan cabang, status akses, dan tanggung jawab workflow.</p></div><div class="ur-kpis"><div><small>TOTAL AKUN</small><b>{{total}}</b></div><div><small>AKUN AKTIF</small><b>{{active_total}}</b></div><div><small>ROLE TERSEDIA</small><b>{{roles|length}}</b></div></div></header><section class="ur-roles">{% for key,r in roles.items() %}<a class="ur-role {{'active' if role_filter==key}}" style="--rc:{{r.color}}" href="{{url_for('users',role=key,status=status_filter,q=q)}}"><i>{{r.short}}</i><b>{{r.label}}</b><small>{{role_counts.get(key,{}).get('active',0)}} aktif · {{role_counts.get(key,{}).get('total',0)}} akun</small></a>{% endfor %}</section><section class="ur-layout"><aside class="ur-form"><h3>Buat Akun Baru</h3><form method="post"><input type="hidden" name="action" value="create"><label>Nama lengkap<input name="full_name" required placeholder="Nama pengguna"></label><label>Username<input name="username" required autocomplete="off" placeholder="Username login"></label><label>Password awal<input type="password" name="password" minlength="8" required autocomplete="new-password" placeholder="Minimal 8 karakter"></label><label>Role<select name="role" id="selRole" onchange="roleChanged()" required>{% for key,r in roles.items() %}<option value="{{key}}">{{r.label}} · {{r.group}}</option>{% endfor %}</select></label><div id="roleHelp" class="ur-role-help"></div><label id="branchWrap" style="display:none">Cabang penempatan<select name="branch_id"><option value="">Pilih cabang</option>{% for b in branches %}<option value="{{b.id}}">{{b.branch_code}} · {{b.name}}</option>{% endfor %}</select></label><label class="ur-toggle"><input type="checkbox" name="activate_now" value="1"> Aktifkan langsung setelah dibuat</label><button class="btn-success">Buat Akun</button></form></aside><section class="ur-list"><div class="kartu"><div><h3>Direktori Pengguna</h3><small>{{rows|length}} akun sesuai filter</small></div><a class="btn btn-sm" href="{{url_for('admin_password_recovery')}}">Pemulihan Password</a></div><form method="get" class="ur-tools"><input name="q" value="{{q}}" placeholder="Cari nama, username, atau cabang"><select name="role"><option value="">Semua role</option>{% for key,r in roles.items() %}<option value="{{key}}" {{'selected' if role_filter==key}}>{{r.label}}</option>{% endfor %}</select><select name="status"><option value="">Semua status</option><option value="active" {{'selected' if status_filter=='active'}}>Aktif</option><option value="inactive" {{'selected' if status_filter=='inactive'}}>Nonaktif</option></select><button>Terapkan</button></form><div class="ur-users">{% for u in rows %}{% set rc=roles.get(u.role,{'short':'?','label':u.role,'color':'#526275'}) %}<article class="ur-user {{'new' if created==u.id}}" style="--uc:{{rc.color}}"><header><i class="ur-avatar">{{rc.short}}</i><div><b>{{u.full_name or u.username}}</b><small>@{{u.username}} · {{rc.label}}</small></div><i class="ur-status {{'on' if u.active}}"></i></header><div class="ur-meta"><span>{{u.branch_code or 'PUSAT / GLOBAL'}}</span><span>{{u.status or ('ACTIVE' if u.active else 'NONACTIVE')}}</span><span>ID {{u.id}}</span></div><footer><small>{{u.branch_name or rc.get('group','Role khusus')}}</small><form method="post"><input type="hidden" name="action" value="toggle_status"><input type="hidden" name="user_id" value="{{u.id}}"><button class="btn btn-sm {{'btn-danger' if u.active else 'btn-success'}}" {{'disabled' if u.id==session.get('user_id')}}>{{'Nonaktifkan' if u.active else 'Aktifkan'}}</button></form></footer></article>{% else %}<div class="ur-empty">Tidak ada akun sesuai filter.</div>{% endfor %}</div></section></section></div><script>const roleData={{roles|tojson}},branchRoles={{branch_roles|list|tojson}};function roleChanged(){const k=document.getElementById('selRole').value,r=roleData[k]||{};document.getElementById('roleHelp').innerHTML='<b>'+String(r.label||k)+'</b><br>'+String(r.desc||'');document.getElementById('branchWrap').style.display=branchRoles.includes(k)?'grid':'none'}roleChanged();</script>'''

# =========================
# Approvals, Accounting, Reports, Audit, Settings
# (These are kept compact since they were already working)
# =========================
@app.route('/approvals', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def approvals():
    if request.method == 'POST':
        approval_id = int(request.form.get('approval_id'))
        action = request.form.get('action')
        note = request.form.get('reason', '').strip()
        ap = q_one('SELECT * FROM approval_requests WHERE id=? AND status="Pending"', [approval_id])
        if not ap:
            flash('Approval request tidak ditemukan / sudah diproses.', 'error')
            return redirect(url_for('approvals'))
        if ap['request_type'] in ('loan_create',):
            loan = q_one('SELECT * FROM loans WHERE id=?', [ap['ref_id']])
            if not loan:
                flash('Data pinjaman tidak ditemukan.', 'error')
                return redirect(url_for('approvals'))
            if action == 'approve':
                new_status = 'Berjalan' if loan['status'] == 'CALCULATED' else 'Berjalan'
                exec_sql('UPDATE approval_requests SET status="Approved", approved_by=?, approved_at=? WHERE id=?', [session.get('user_id'), now_str(), approval_id])
                exec_sql('UPDATE loans SET status=?, approved_by=?, approved_at=? WHERE id=?', [new_status, session.get('user_id'), now_str(), loan['id']])
                add_timeline(loan['id'], new_status, 'Pinjaman disetujui oleh admin')
                log_action('APPROVE', 'approval_requests', approval_id, f'Approve loan {loan["loan_no"]}')
                flash('Pinjaman disetujui dan diposting.', 'success')
            else:
                exec_sql('UPDATE approval_requests SET status="Rejected", approved_by=?, approved_at=?, reason=? WHERE id=?', [session.get('user_id'), now_str(), note or ap['reason'], approval_id])
                exec_sql('UPDATE loans SET status="Ditolak" WHERE id=?', [loan['id']])
                add_timeline(loan['id'], 'DITOLAK', note or ap.get('reason', ''))
                log_action('REJECT', 'approval_requests', approval_id, f'Reject loan {loan["loan_no"]}')
                flash('Pinjaman ditolak.', 'warning')
        elif ap['request_type'] == 'sales_void':
            sale = q_one('SELECT * FROM sales WHERE id=?', [ap['ref_id']])
            if not sale:
                flash('Data sales tidak ditemukan.', 'error')
                return redirect(url_for('approvals'))
            if action == 'approve':
                items = q_all('SELECT * FROM sales_items WHERE sales_id=?', [sale['id']])
                for it in items:
                    update_branch_stock(it['product_id'],it['qty'],sale['branch_id'],'add')
                exec_sql('UPDATE approval_requests SET status="Approved", approved_by=?, approved_at=? WHERE id=?', [session.get('user_id'), now_str(), approval_id])
                exec_sql('UPDATE sales SET status="Void" WHERE id=?', [sale['id']])
                log_action('APPROVE', 'approval_requests', approval_id, f'Approve void {sale["invoice_no"]}')
                flash('Void transaksi disetujui.', 'success')
            else:
                exec_sql('UPDATE approval_requests SET status="Rejected", approved_by=?, approved_at=?, reason=? WHERE id=?', [session.get('user_id'), now_str(), note or ap['reason'], approval_id])
                exec_sql('UPDATE sales SET status="Posted" WHERE id=?', [sale['id']])
                log_action('REJECT', 'approval_requests', approval_id, f'Reject void {sale["invoice_no"]}')
                flash('Void transaksi ditolak.', 'warning')
        return redirect(url_for('approvals'))
    rows = q_all("SELECT a.*, u.full_name as creator_name FROM approval_requests a LEFT JOIN users u ON u.id=a.created_by WHERE a.status='Pending' ORDER BY a.id DESC")
    hist = q_all("SELECT a.*, u.full_name as creator_name, ua.full_name as approver_name FROM approval_requests a LEFT JOIN users u ON u.id=a.created_by LEFT JOIN users ua ON ua.id=a.approved_by ORDER BY a.id DESC LIMIT 200")
    body = render_template_string("""<div class="card"><h2>👌 Approval Requests</h2><div class="table-wrap"><table><thead><tr><th>Jenis</th><th>Pemohon</th><th>Alasan</th><th>Aksi</th></tr></thead><tbody>{% for r in rows %}<tr><td>{{ r.request_type }}</td><td>{{ r.creator_name or '-' }}</td><td>{{ r.reason }}</td><td><form method="post" style="display:flex;gap:8px;"><input type="hidden" name="approval_id" value="{{ r.id }}"><button name="action" value="approve" class="btn-sm btn-success">✅</button><button name="action" value="reject" class="btn-sm btn-danger">❌</button></form></td></tr>{% else %}<tr><td colspan="4" class="muted text-center">Tidak ada pending.</td></tr>{% endfor %}</tbody></table></div><hr><h3>Riwayat</h3><div class="table-wrap"><table><thead><tr><th>Jenis</th><th>Status</th><th>Pemohon</th></tr></thead><tbody>{% for r in hist %}<tr><td>{{ r.request_type }}</td><td><span class="badge {% if r.status == 'Approved' %}badge-success{% else %}badge-danger{% endif %}">{{ r.status }}</span></td><td>{{ r.creator_name or '-' }}</td></tr>{% else %}<tr><td colspan="3" class="muted text-center">Belum ada.</td></tr>{% endfor %}</tbody></table></div></div>""", rows=rows, hist=hist)
    return render_page('Approval', body)

@app.route('/accounting', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'bendahara')
def accounting():
    if request.method == 'POST':
        action = request.form.get('action')
        if action == 'add_account':
            code = request.form.get('account_code', '').strip()
            name = request.form.get('account_name', '').strip()
            category = request.form.get('category', 'Aset')
            normal = request.form.get('normal_balance', 'Debit')
            try:
                exec_sql('INSERT INTO accounts(account_code, account_name, category, normal_balance) VALUES (?, ?, ?, ?)', [code, name, category, normal])
                flash('Akun berhasil ditambahkan.', 'success')
                return redirect(url_for('accounting'))
            except sqlite3.IntegrityError:
                flash('Kode akun sudah ada.', 'error')
    coa = q_all('SELECT * FROM accounts ORDER BY account_code ASC')
    journal = q_all('SELECT j.entry_no, j.entry_date, j.description, a.account_code, a.account_name, j.debit, j.credit FROM journal_entries j LEFT JOIN accounts a ON a.id=j.account_id ORDER BY j.id DESC LIMIT 400')
    body = render_template_string('<div class="card"><h2>📒 Akuntansi</h2><div class="grid"><div class="col-4"><h3>Tambah Akun</h3><form method="post"><input type="hidden" name="action" value="add_account"><div class="form-group"><label>Kode</label><input name="account_code" placeholder="Kode"></div><div class="form-group"><label>Nama</label><input name="account_name" placeholder="Nama akun"></div><div class="form-group"><label>Kategori</label><select name="category"><option>Aset</option><option>Kewajiban</option><option>Modal</option><option>Pendapatan</option><option>Beban</option></select></div><div class="form-group"><label>Saldo Normal</label><select name="normal_balance"><option>Debit</option><option>Kredit</option></select></div><button type="submit">Simpan</button></form></div><div class="col-8"><h3>COA</h3><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama</th><th>Kategori</th></tr></thead><tbody>{% for a in coa %}<tr><td>{{ a.account_code }}</td><td>{{ a.account_name }}</td><td>{{ a.category }}</td></tr>{% else %}<tr><td colspan="3" class="muted text-center">Belum ada.</td></tr>{% endfor %}</tbody></table></div><hr><h3>Jurnal</h3><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Deskripsi</th><th>Akun</th><th>Debit</th><th>Kredit</th></tr></thead><tbody>{% for j in journal %}<tr><td>{{ j.entry_date }}</td><td>{{ j.description }}</td><td>{{ j.account_code }} — {{ j.account_name }}</td><td>{{ rupiah(j.debit) }}</td><td>{{ rupiah(j.credit) }}</td></tr>{% else %}<tr><td colspan="5" class="muted text-center">Belum ada jurnal.</td></tr>{% endfor %}</tbody></table></div></div></div></div>', coa=coa, journal=journal, rupiah=rupiah)
    return render_page('Akuntansi', body)

