@app.route('/member/expense-history')
@login_required
def member_expense_history():
    user = current_user()
    member = q_one('SELECT * FROM members WHERE member_code = ?', [f'EMP-{user["employee_number"]}'])
    if not member:
        flash('Akun member tidak ditemukan.', 'warning')
        return redirect(url_for('dashboard'))
    
    year = request.args.get('year', str(datetime.now().year))
    month = request.args.get('month', str(datetime.now().month).zfill(2))
    cat_filter = request.args.get('cat', 'all')
    
    # Get all wallet outflows (belanja, pembayaran, dll)
    wallet_out = q_all('''
        SELECT id, tipe, nominal, keterangan, created_at, created_by
        FROM saldo_history 
        WHERE member_id = ? AND tipe = 'KELUAR'
        AND strftime('%Y-%m', created_at) = ?
        ORDER BY created_at DESC
    ''', [member['id'], f'{year}-{month}'])
    
    # Get all wallet inflows (topup)
    wallet_in = q_all('''
        SELECT id, tipe, nominal, keterangan, created_at, created_by
        FROM saldo_history 
        WHERE member_id = ? AND tipe = 'MASUK'
        AND strftime('%Y-%m', created_at) = ?
        ORDER BY created_at DESC
    ''', [member['id'], f'{year}-{month}'])
    
    # Get loan payments for current member
    loan_payments = q_all('''
        SELECT lp.id, lp.payment_date, lp.amount, lp.penalty_amount, lp.status,
               l.loan_no, l.total_receivable
        FROM loan_payments lp
        JOIN loans l ON l.id = lp.loan_id
        WHERE l.member_id = ?
        AND strftime('%Y-%m', lp.payment_date) = ?
        ORDER BY lp.payment_date DESC
    ''', [member['id'], f'{year}-{month}'])
    
    # Get savings transactions (keluar - penarikan)
    savings_out = q_all('''
        SELECT id, trx_no, trx_date, saving_type, direction, amount, note
        FROM savings_transactions
        WHERE member_id = ? AND direction = 'Keluar'
        AND strftime('%Y-%m', trx_date) = ?
        ORDER BY trx_date DESC
    ''', [member['id'], f'{year}-{month}'])
    
    # Combine all into unified transaction list
    all_tx = []
    for tx in wallet_out:
        all_tx.append({
            'date': tx['created_at'],
            'category': 'Pembayaran',
            'description': tx['keterangan'] or 'Pembayaran via wallet',
            'amount': -float(tx['nominal']),
            'type': 'debit',
            'badge': 'badge-danger'
        })
    for tx in wallet_in:
        all_tx.append({
            'date': tx['created_at'],
            'category': 'Topup',
            'description': tx['keterangan'] or 'Saldo masuk',
            'amount': float(tx['nominal']),
            'type': 'credit',
            'badge': 'badge-success'
        })
    for tx in loan_payments:
        all_tx.append({
            'date': tx['payment_date'],
            'category': 'Angsuran Pinjaman',
            'description': f'Pembayaran angsuran {tx["loan_no"]}',
            'amount': -float(tx['amount']),
            'type': 'debit',
            'badge': 'badge-danger'
        })
    for tx in savings_out:
        all_tx.append({
            'date': tx['trx_date'],
            'category': 'Penarikan Simpanan',
            'description': f'{tx["saving_type"]} - {tx["direction"]}',
            'amount': -float(tx['amount']),
            'type': 'debit',
            'badge': 'badge-warn'
        })
    
    # Sort by date descending
    all_tx.sort(key=lambda x: x['date'], reverse=True)
    
    # Monthly summary
    total_out = abs(sum(t['amount'] for t in all_tx if t['amount'] < 0))
    total_in = sum(t['amount'] for t in all_tx if t['amount'] > 0)
    
    body = render_template_string('''
    <div class="card">
        <div class="kartu">
            <div>
                <h2>📊 Riwayat Transaksi Bulanan</h2>
                <div class="muted small">{{ member.member_code }} — {{ member.name }}</div>
            </div>
            <form method="get" style="display:flex;gap:8px;flex-wrap:wrap;align-items:end;">
                <div>
                    <label class="small muted">Tahun</label>
                    <select name="year" onchange="this.form.submit()" style="width:100px;">
                        {% for y in range(2024, 2028) %}
                            <option value="{{ y }}" {% if y|string == year %}selected{% endif %}>{{ y }}</option>
                        {% endfor %}
                    </select>
                </div>
                <div>
                    <label class="small muted">Bulan</label>
                    <select name="month" onchange="this.form.submit()" style="width:120px;">
                        {% for m in range(1, 13) %}
                            <option value="{{ '%02d'|format(m) }}" {% if '%02d'|format(m) == month %}selected{% endif %}>{{ ['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep','Okt','Nov','Des'][m-1] }}</option>
                        {% endfor %}
                    </select>
                </div>
                <div>
                    <label class="small muted">Kategori</label>
                    <select name="cat" onchange="this.form.submit()" style="width:120px;">
                        <option value="all" {% if cat_filter == 'all' %}selected{% endif %}>Semua</option>
                        <option value="Pembayaran" {% if cat_filter == 'Pembayaran' %}selected{% endif %}>Pembayaran</option>
                        <option value="Angsuran Pinjaman" {% if cat_filter == 'Angsuran Pinjaman' %}selected{% endif %}>Angsuran Pinjaman</option>
                        <option value="Topup" {% if cat_filter == 'Topup' %}selected{% endif %}>Topup</option>
                        <option value="Penarikan Simpanan" {% if cat_filter == 'Penarikan Simpanan' %}selected{% endif %}>Penarikan</option>
                    </select>
                </div>
            </form>
        </div>
    </div>
    
    <div class="metrics">
        <div class="metric" style="background:linear-gradient(135deg,#ecfdf5,#d1fae5);border-color:#6ee7b7;">
            <div class="label">Total Masuk</div>
            <div class="value" style="color:#10b981;">{{ rupiah(total_in) }}</div>
            <div class="sub">{{ month_names[month|int - 1] }} {{ year }}</div>
        </div>
        <div class="metric" style="background:linear-gradient(135deg,#fef2f2,#fee2e2);border-color:#fca5a5;">
            <div class="label">Total Keluar</div>
            <div class="value" style="color:#ef4444;">{{ rupiah(total_out) }}</div>
            <div class="sub">{{ month_names[month|int - 1] }} {{ year }}</div>
        </div>
        <div class="metric" style="background:linear-gradient(135deg,#eff6ff,#dbeafe);border-color:#93c5fd;">
            <div class="label">Transaksi</div>
            <div class="value" style="color:#2563eb;">{{ all_tx|length }}</div>
            <div class="sub">Total transaksi bulan ini</div>
        </div>
        <div class="metric" style="background:white;">
            <div class="label">Saldo Aktual</div>
            <div class="value" style="color:#4f46e5;">{{ rupiah(saldo_wallet) }}</div>
            <div class="sub">wallet saat ini</div>
        </div>
    </div>
    
    <div class="card">
        <h2 style="font-size:16px;margin-bottom:14px;">📑 Daftar Transaksi — {{ month_names[month|int - 1] }} {{ year }}</h2>
        <div class="table-wrap">
            <table>
                <thead>
                    <tr>
                        <th>Tanggal</th>
                        <th>Kategori</th>
                        <th>Keterangan</th>
                        <th>Jumlah</th>
                    </tr>
                </thead>
                <tbody>
                    {% for tx in filtered_tx %}
                    <tr style="border-left:3px solid {% if tx.type == 'credit' %}#10b981{% elif tx.type == 'debit' %}#ef4444{% else %}#f59e0b{% endif %};">
                        <td>
                            <div style="font-size:12px;color:var(--text-muted);">{{ tx.date[:10] }}</div>
                            <div style="font-size:11px;color:var(--text-muted);">{{ tx.date[11:16] }} WIB</div>
                        </td>
                        <td>
                            <span class="badge {{ tx.badge }}">{{ tx.category }}</span>
                        </td>
                        <td>
                            <div style="font-size:13px;font-weight:500;">{{ tx.description }}</div>
                        </td>
                        <td style="text-align:right;">
                            <div style="font-size:15px;font-weight:700;color:{{ '#10b981' if tx.type == 'credit' else '#ef4444' }};">
                                {{ '+' if tx.type == 'credit' else '' }}{{ rupiah(tx.amount|abs|round(0)) }}
                            </div>
                        </td>
                    </tr>
                    {% else %}
                    <tr>
                        <td colspan="4" class="muted text-center">Tidak ada transaksi bulan ini.</td>
                    </tr>
                    {% endfor %}
                </tbody>
                <tfoot>
                    <tr style="background:var(--bg);font-weight:700;">
                        <td colspan="3">Total Bulan Ini</td>
                        <td style="text-align:right;font-size:15px;">
                            <span style="color:#10b981;">{{ rupiah(total_in) }}</span> masuk /
                            <span style="color:#ef4444;">{{ rupiah(total_out) }}</span> keluar
                        </td>
                    </tr>
                </tfoot>
            </table>
        </div>
    </div>
    
    <div class="card">
        <h3 style="margin-bottom:12px;">📌 Keterangan Kategori</h3>
        <div style="display:flex;gap:12px;flex-wrap:wrap;font-size:12px;">
            <span><span class="badge badge-danger">Pembayaran</span> Pembayaran via wallet (belanja, dll)</span>
            <span><span class="badge badge-danger">Angsuran Pinjaman</span> Pembayaran angsuran pinjaman</span>
            <span><span class="badge badge-success">Topup</span> Saldo masuk dari topup</span>
            <span><span class="badge badge-warn">Penarikan Simpanan</span> Penarikan simpanan</span>
        </div>
    </div>
    ''', member=member, all_tx=all_tx, 
        filtered_tx=[t for t in all_tx if cat_filter == 'all' or t['category'] == cat_filter],
        year=year, month=month, cat_filter=cat_filter,
        total_in=total_in, total_out=total_out,
        saldo_wallet=q_one('SELECT COALESCE(SUM(CASE WHEN tipe="MASUK" THEN nominal ELSE -nominal END), 0) as saldo FROM saldo_history WHERE member_id=?', [member['id']])['saldo'],
        month_names=['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'],
        rupiah=rupiah)
    return render_page('Riwayat Transaksi', body)

# =========================
# Bubble Notifications (JSON API)
# =========================
@app.route('/api/sidebar-badges')
@login_required
def api_sidebar_badges():
    user = current_user()
    return jsonify({'ok': True, 'badges': get_sidebar_badge_counts(user), 'server_time': now_str()})

@app.route('/api/notifications')
@login_required
def api_notifications():
    user = current_user()
    # Keep inbox bounded without marking or deleting recent unread notifications when popup opens.
    exec_sql('DELETE FROM notifications WHERE user_id=? AND ((is_read=1 AND created_at<datetime("now","-7 days")) OR created_at<datetime("now","-90 days"))',[user['id']])
    try:
        limit=max(1,min(50,int(request.args.get('limit',20) or 20)))
    except (TypeError,ValueError):
        limit=20
    # Default response is always the latest inbox snapshot. since_id remains optional for external polling clients.
    try:
        since_id=max(0,int(request.args.get('since_id',0) or 0))
    except (TypeError,ValueError):
        since_id=0
    if since_id:
        rows=q_all('SELECT id,title,message,is_read,created_at FROM notifications WHERE user_id=? AND id>? ORDER BY id DESC LIMIT ?',[user['id'],since_id,limit])
    else:
        rows=q_all('SELECT id,title,message,is_read,created_at FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT ?',[user['id'],limit])
    counts=q_one('SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN is_read=0 THEN 1 ELSE 0 END),0) unread FROM notifications WHERE user_id=?',[user['id']])
    items=[{'id':r['id'],'title':r['title'] or 'Notifikasi','message':r['message'] or '','is_read':int(r['is_read'] or 0),'created_at':r['created_at'] or ''} for r in rows]
    latest=q_one('SELECT COALESCE(MAX(id),0) max_id FROM notifications WHERE user_id=?',[user['id']])
    response=jsonify({'ok':True,'notifications':items,'unread':int(counts['unread'] or 0),'total':int(counts['total'] or 0),'returned':len(items),'max_id':int(latest['max_id'] or 0)})
    response.headers['Cache-Control']='no-store, no-cache, must-revalidate, max-age=0'
    response.headers['Pragma']='no-cache'
    return response

@app.route('/api/notifications/read/<int:notif_id>', methods=['POST'])
@login_required
def api_notifications_read(notif_id):
    exec_sql('UPDATE notifications SET is_read = 1 WHERE id = ? AND user_id = ?', [notif_id, session['user_id']])
    return jsonify({'ok': True})

@app.route('/api/notifications/read-all', methods=['POST'])
@login_required
def api_notifications_read_all():
    exec_sql('UPDATE notifications SET is_read = 1 WHERE user_id = ? AND is_read = 0', [session['user_id']])
    return jsonify({'ok': True})

