@app.route('/notifications')
@login_required
def notifications():
    user = current_user()
    rows = q_all('SELECT * FROM notifications WHERE user_id = ? ORDER BY id DESC LIMIT 100', [user['id']])
    unread = q_one('SELECT COUNT(*) as n FROM notifications WHERE user_id = ? AND is_read = 0', [user['id']])['n'] or 0
    body = render_template_string('''
    <div class="card">
        <div class="kartu">
            <div><h2>🔔 Notifikasi</h2><div class="muted small">{{ unread }} belum dibaca</div></div>
            <div class="top-actions">
                <form method="POST" action="{{ url_for('notifications_read_all') }}" style="display:inline;">
                    <button class="btn btn-sm btn-ghost">✅ Tandai Semua Dibaca</button>
                </form>
            </div>
        </div>
        <div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Judul</th><th>Pesan</th><th>Status</th><th>Aksi</th></tr></thead>
        <tbody>{% for r in rows %}<tr style="{{ 'font-weight:600;' if not r.is_read else '' }}">
            <td class="muted small">{{ r.created_at }}</td>
            <td>{{ r.title }}</td>
            <td>{{ r.message }}</td>
            <td>{% if r.is_read %}<span class="badge badge-gray">Dibaca</span>{% else %}<span class="badge badge-info">Baru</span>{% endif %}</td>
            <td>{% if not r.is_read %}<form method="POST" action="{{ url_for('notifications_read', notif_id=r.id) }}" style="display:inline;"><button class="btn-sm btn-ghost">✅</button></form>{% endif %}</td>
        </tr>{% else %}<tr><td colspan="5" class="muted text-center">Belum ada notifikasi.</td></tr>{% endfor %}</tbody></table></div>
    </div>
    ''', rows=rows, unread=unread)
    return render_page('Notifikasi', body)

@app.route('/notifications/read/<int:notif_id>', methods=['POST'])
@login_required
def notifications_read(notif_id):
    exec_sql('UPDATE notifications SET is_read = 1 WHERE id = ? AND user_id = ?', [notif_id, session['user_id']])
    return redirect(request.referrer or url_for('notifications'))


@app.route('/api/notifications/clear',methods=['POST'])
@login_required
def notifications_clear_api():
    uid=session.get('user_id')
    exec_sql('DELETE FROM notifications WHERE user_id=? AND (is_read=1 OR created_at<datetime("now","-30 days"))',[uid])
    try:
        ensure_payment_code_schema()
        exec_sql('UPDATE durable_notifications SET dismissed_at=? WHERE user_id=? AND dismissed_at IS NULL',[now_str(),uid])
        exec_sql('DELETE FROM durable_notifications WHERE user_id=? AND (dismissed_at IS NOT NULL OR created_at<datetime("now","-30 days"))',[uid])
    except Exception: pass
    return jsonify({'ok':True})

@app.route('/notifications/read-all', methods=['POST'])
@login_required
def notifications_read_all():
    exec_sql('UPDATE notifications SET is_read = 1 WHERE user_id = ? AND is_read = 0', [session['user_id']])
    flash('Semua notifikasi ditandai dibaca.', 'success')
    return redirect(url_for('notifications'))

