# ==========================================================
# PAYMENT ACCOUNT GOVERNANCE + ADMIN COMMAND CENTER V24
# ==========================================================

def ensure_payment_account_schema():
    conn=get_conn(); c=conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS payment_accounts(
      id INTEGER PRIMARY KEY AUTOINCREMENT,bank_name TEXT NOT NULL,account_number TEXT NOT NULL,
      account_holder TEXT NOT NULL,account_type TEXT DEFAULT 'KREDIT',branch_id INTEGER,currency TEXT DEFAULT 'IDR',
      instructions TEXT,status TEXT DEFAULT 'ACTIVE',is_default INTEGER DEFAULT 0,version_no INTEGER DEFAULT 1,
      effective_from TEXT DEFAULT CURRENT_TIMESTAMP,effective_until TEXT,created_by INTEGER,created_at TEXT DEFAULT CURRENT_TIMESTAMP,
      updated_by INTEGER,updated_at TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS payment_account_history(
      id INTEGER PRIMARY KEY AUTOINCREMENT,payment_account_id INTEGER,action TEXT,old_data TEXT,new_data TEXT,
      reason TEXT,changed_by INTEGER,changed_at TEXT DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY(payment_account_id) REFERENCES payment_accounts(id))''')
    required={
      'bank_name':'TEXT','account_number':'TEXT','account_holder':'TEXT','account_type':'TEXT DEFAULT "KREDIT"',
      'branch_id':'INTEGER','currency':'TEXT DEFAULT "IDR"','instructions':'TEXT','status':'TEXT DEFAULT "ACTIVE"',
      'is_default':'INTEGER DEFAULT 0','version_no':'INTEGER DEFAULT 1','effective_from':'TEXT','effective_until':'TEXT',
      'created_by':'INTEGER','created_at':'TEXT','updated_by':'INTEGER','updated_at':'TEXT'}
    existing={r['name'] for r in c.execute('PRAGMA table_info(payment_accounts)').fetchall()}
    for name,definition in required.items():
        if name not in existing: c.execute(f'ALTER TABLE payment_accounts ADD COLUMN {name} {definition}')
    hist_required={'payment_account_id':'INTEGER','action':'TEXT','old_data':'TEXT','new_data':'TEXT','reason':'TEXT','changed_by':'INTEGER','changed_at':'TEXT'}
    hist_existing={r['name'] for r in c.execute('PRAGMA table_info(payment_account_history)').fetchall()}
    for name,definition in hist_required.items():
        if name not in hist_existing: c.execute(f'ALTER TABLE payment_account_history ADD COLUMN {name} {definition}')
    c.execute('CREATE INDEX IF NOT EXISTS idx_payment_accounts_type_status ON payment_accounts(account_type,status)')
    c.execute('CREATE INDEX IF NOT EXISTS idx_payment_history_account ON payment_account_history(payment_account_id,changed_at)')
    conn.commit(); conn.close()

def payment_account_payload(row):
    return json.dumps({k:row[k] for k in row.keys()},ensure_ascii=False,default=str) if row else None

def normalize_account_number(value):
    return ''.join(ch for ch in (value or '').strip() if ch.isalnum() or ch in '- ')

@app.route('/admin/payment-accounts',methods=['GET','POST'])
@login_required
@role_required('admin','bendahara')
def payment_accounts():
    ensure_payment_account_schema(); user=current_user()
    if request.method=='POST':
        action=(request.form.get('action') or 'create').strip().lower(); reason=(request.form.get('reason') or '').strip()[:300]
        conn=get_conn()
        try:
            conn.execute('BEGIN IMMEDIATE')
            if action=='create':
                bank=(request.form.get('bank_name') or '').strip()[:80]
                number=normalize_account_number(request.form.get('account_number'))[:60]
                holder=(request.form.get('account_holder') or '').strip()[:100]
                account_type=(request.form.get('account_type') or 'KREDIT').upper()
                currency=(request.form.get('currency') or 'IDR').upper()
                instructions=(request.form.get('instructions') or '').strip()[:500]
                if len(bank)<2: raise ValueError('Nama bank atau penyedia minimal 2 karakter.')
                if len(number)<5: raise ValueError('Nomor rekening minimal 5 karakter.')
                if len(holder)<3: raise ValueError('Nama pemilik rekening minimal 3 karakter.')
                if account_type not in ('KREDIT','EWALLET','SEMUA'): raise ValueError('Jenis penggunaan rekening tidak valid.')
                duplicate=conn.execute('SELECT id FROM payment_accounts WHERE UPPER(bank_name)=UPPER(?) AND REPLACE(account_number," ","")=REPLACE(?," ","")',[bank,number]).fetchone()
                if duplicate: raise ValueError('Rekening tersebut sudah terdaftar.')
                make_default=1 if request.form.get('is_default') else 0
                active_credit=conn.execute("SELECT COUNT(*) n FROM payment_accounts WHERE status='ACTIVE' AND account_type IN ('KREDIT','SEMUA')").fetchone()['n']
                if account_type in ('KREDIT','SEMUA') and active_credit==0: make_default=1
                if make_default and account_type in ('KREDIT','SEMUA'):
                    conn.execute("UPDATE payment_accounts SET is_default=0 WHERE account_type IN ('KREDIT','SEMUA')")
                cur=conn.execute('''INSERT INTO payment_accounts
                  (bank_name,account_number,account_holder,account_type,currency,instructions,status,is_default,version_no,effective_from,created_by,created_at)
                  VALUES(?,?,?,?,?,?,"ACTIVE",?,1,?,?,?)''',[bank,number,holder,account_type,currency,instructions,make_default,now_str(),user['id'],now_str()])
                rid=cur.lastrowid; row=conn.execute('SELECT * FROM payment_accounts WHERE id=?',[rid]).fetchone()
                conn.execute('INSERT INTO payment_account_history(payment_account_id,action,new_data,reason,changed_by,changed_at) VALUES(?,?,?,?,?,?)',[rid,'CREATE',payment_account_payload(row),reason or 'Pembuatan rekening baru',user['id'],now_str()])
                conn.commit(); log_action('PAYMENT_ACCOUNT_CREATE','payment_accounts',rid,f'{bank}; {number}'); flash('Rekening pembayaran berhasil ditambahkan.','success')
            elif action in ('update','toggle'):
                rid=int(request.form.get('account_id') or 0); old=conn.execute('SELECT * FROM payment_accounts WHERE id=?',[rid]).fetchone()
                if not old: raise ValueError('Rekening tidak ditemukan.')
                if len(reason)<5: raise ValueError('Alasan perubahan minimal 5 karakter.')
                if action=='toggle':
                    new_status='INACTIVE' if old['status']=='ACTIVE' else 'ACTIVE'
                    if new_status=='INACTIVE' and int(old['is_default'] or 0)==1:
                        replacement=conn.execute("SELECT id FROM payment_accounts WHERE id<>? AND status='ACTIVE' AND account_type IN ('KREDIT','SEMUA') ORDER BY is_default DESC,id LIMIT 1",[rid]).fetchone()
                        if not replacement: raise ValueError('Rekening utama tidak dapat dinonaktifkan sebelum ada rekening kredit aktif pengganti.')
                        conn.execute('UPDATE payment_accounts SET is_default=1 WHERE id=?',[replacement['id']])
                    conn.execute('UPDATE payment_accounts SET status=?,is_default=CASE WHEN ?="INACTIVE" THEN 0 ELSE is_default END,effective_until=?,updated_by=?,updated_at=?,version_no=COALESCE(version_no,1)+1 WHERE id=?',[new_status,new_status,now_str() if new_status=='INACTIVE' else None,user['id'],now_str(),rid])
                else:
                    bank=(request.form.get('bank_name') or '').strip()[:80]; number=normalize_account_number(request.form.get('account_number'))[:60]; holder=(request.form.get('account_holder') or '').strip()[:100]
                    account_type=(request.form.get('account_type') or 'KREDIT').upper(); currency=(request.form.get('currency') or 'IDR').upper(); instructions=(request.form.get('instructions') or '').strip()[:500]
                    if len(bank)<2 or len(number)<5 or len(holder)<3: raise ValueError('Data bank, nomor rekening, atau pemilik belum valid.')
                    duplicate=conn.execute('SELECT id FROM payment_accounts WHERE id<>? AND UPPER(bank_name)=UPPER(?) AND REPLACE(account_number," ","")=REPLACE(?," ","")',[rid,bank,number]).fetchone()
                    if duplicate: raise ValueError('Rekening tersebut sudah digunakan oleh data lain.')
                    make_default=1 if request.form.get('is_default') else 0
                    if make_default and account_type in ('KREDIT','SEMUA'): conn.execute("UPDATE payment_accounts SET is_default=0 WHERE id<>? AND account_type IN ('KREDIT','SEMUA')",[rid])
                    conn.execute('''UPDATE payment_accounts SET bank_name=?,account_number=?,account_holder=?,account_type=?,currency=?,instructions=?,is_default=?,updated_by=?,updated_at=?,version_no=COALESCE(version_no,1)+1 WHERE id=?''',[bank,number,holder,account_type,currency,instructions,make_default,user['id'],now_str(),rid])
                newrow=conn.execute('SELECT * FROM payment_accounts WHERE id=?',[rid]).fetchone()
                conn.execute('INSERT INTO payment_account_history(payment_account_id,action,old_data,new_data,reason,changed_by,changed_at) VALUES(?,?,?,?,?,?,?)',[rid,action.upper(),payment_account_payload(old),payment_account_payload(newrow),reason,user['id'],now_str()])
                conn.commit(); log_action('PAYMENT_ACCOUNT_'+action.upper(),'payment_accounts',rid,reason); flash('Perubahan rekening berhasil disimpan dan direkam.','success')
            else: raise ValueError('Tindakan rekening tidak dikenali.')
        except (ValueError,sqlite3.IntegrityError) as e:
            conn.rollback(); flash(str(e) if isinstance(e,ValueError) else 'Data rekening bertabrakan dengan data yang sudah ada.','error')
        except Exception as e:
            conn.rollback(); log_action('PAYMENT_ACCOUNT_ERROR','payment_accounts','',f'{type(e).__name__}: {e}'); flash(f'Gagal menyimpan rekening: {e}','error')
        finally: conn.close()
        return redirect(url_for('payment_accounts'))
    edit_id=request.args.get('edit',type=int); edit=q_one('SELECT * FROM payment_accounts WHERE id=?',[edit_id]) if edit_id else None
    rows=q_all('SELECT * FROM payment_accounts ORDER BY CASE status WHEN "ACTIVE" THEN 0 ELSE 1 END,is_default DESC,id DESC')
    history=q_all('SELECT h.*,u.full_name FROM payment_account_history h LEFT JOIN users u ON u.id=h.changed_by ORDER BY h.id DESC LIMIT 100')
    active_count=sum(1 for r in rows if r['status']=='ACTIVE'); default_count=sum(1 for r in rows if r['is_default'])
    body=render_template_string(r'''<div class="bank-suite"><header class="bank-hero"><div><span>PAYMENT ROUTING</span><h2>Rekening Pembayaran</h2><p>Kelola rekening resmi koperasi dengan validasi, versioning, snapshot transaksi, dan histori perubahan.</p></div><div class="bank-hero-stats"><article><b>{{active_count}}</b><small>Aktif</small></article><article><b>{{rows|length}}</b><small>Total</small></article><article><b>{{default_count}}</b><small>Utama</small></article></div></header><div class="bank-layout"><aside class="bank-form"><h3>{{'Perbarui rekening' if edit else 'Tambah rekening'}}</h3><p class="bank-form-note">Data rekening akan digunakan sebagai tujuan resmi pembayaran anggota.</p><form method="post"><input type="hidden" name="action" value="{{'update' if edit else 'create'}}">{% if edit %}<input type="hidden" name="account_id" value="{{edit.id}}">{% endif %}<label>Bank / penyedia<input name="bank_name" value="{{edit.bank_name if edit else ''}}" minlength="2" required></label><label>Nomor rekening<input name="account_number" value="{{edit.account_number if edit else ''}}" minlength="5" required></label><label>Nama pemilik<input name="account_holder" value="{{edit.account_holder if edit else ''}}" minlength="3" required></label><div class="bank-two"><label>Digunakan untuk<select name="account_type"><option value="KREDIT" {% if edit and edit.account_type=='KREDIT' %}selected{% endif %}>Kredit</option><option value="EWALLET" {% if edit and edit.account_type=='EWALLET' %}selected{% endif %}>E-Wallet</option><option value="SEMUA" {% if edit and edit.account_type=='SEMUA' %}selected{% endif %}>Semua</option></select></label><label>Mata uang<select name="currency"><option value="IDR" {% if not edit or edit.currency=='IDR' %}selected{% endif %}>IDR</option><option value="JPY" {% if edit and edit.currency=='JPY' %}selected{% endif %}>JPY</option></select></label></div><label>Instruksi pembayaran<textarea name="instructions" placeholder="Contoh: Cantumkan nomor kredit pada berita transfer">{{edit.instructions if edit else ''}}</textarea></label><label class="bank-check"><input type="checkbox" name="is_default" {% if edit and edit.is_default %}checked{% endif %}> Jadikan rekening utama kredit</label><label>Alasan perubahan {% if not edit %}<small>(opsional)</small>{% endif %}<input name="reason" placeholder="Contoh: rekening operasional baru" {% if edit %}minlength="5" required{% endif %}></label><button type="submit">{{'Simpan perubahan' if edit else 'Tambahkan rekening'}}</button>{% if edit %}<a href="{{url_for('payment_accounts')}}" class="btn btn-ghost">Batal edit</a>{% endif %}</form></aside><main><div class="bank-grid">{% for a in rows %}<article class="{{'inactive' if a.status!='ACTIVE'}}"><header><i>{{a.bank_name[:3]|upper}}</i><span>{{a.account_type}}</span></header><h3>{{a.account_number}}</h3><p>a.n. {{a.account_holder}}</p><div><b>{{a.status}}</b><small>Versi {{a.version_no or 1}}</small>{% if a.is_default %}<em>UTAMA</em>{% endif %}</div><footer><a href="?edit={{a.id}}">Edit</a><form method="post"><input type="hidden" name="action" value="toggle"><input type="hidden" name="account_id" value="{{a.id}}"><input name="reason" placeholder="Alasan perubahan" minlength="5" required><button type="submit">{{'Nonaktifkan' if a.status=='ACTIVE' else 'Aktifkan'}}</button></form></footer></article>{% else %}<div class="bank-empty"><i>＋</i><h3>Belum ada rekening</h3><p>Tambahkan rekening kredit pertama melalui form di sebelah kiri.</p></div>{% endfor %}</div><section class="bank-history"><h3>Histori Perubahan</h3>{% for h in history %}<div><i></i><span><b>{{h.action}}</b><small>{{h.full_name or '-'}} · {{h.changed_at}}</small><p>{{h.reason or '-'}}</p></span></div>{% else %}<div class="bank-empty-small">Belum ada histori perubahan.</div>{% endfor %}</section></main></div></div>''',rows=rows,edit=edit,history=history,active_count=active_count,default_count=default_count)
    return render_page('Rekening Pembayaran',body)

